mkdir -p /workspace/tools && cat > /workspace/tools/dump_ucd.pl <<'EOF'
# Dumps Unicode inversion lists for the properties needed by the regex engine.
# Output format: one property per line: "<key>\t<cp1>,<cp2>,..."
use strict;
use warnings;
use Unicode::UCD qw(prop_invlist prop_values prop_value_aliases prop_aliases);

sub emit {
    my ($key, @list) = @_;
    return unless @list;
    print $key, "\t", join(",", @list), "\n";
}

# General_Category, Script, Script_Extensions, break properties, Age
for my $prop (qw(gc sc scx GCB SB WB age)) {
    for my $val (prop_values($prop)) {
        my @l = prop_invlist("$prop=$val");
        next unless @l;
        my @names = ($val, prop_value_aliases($prop, $val));
        emit(join("|", $prop, @names), @l);
    }
}

# Binary properties
my @bin = qw(
    Alphabetic ASCII_Hex_Digit Bidi_Control Bidi_Mirrored Case_Ignorable Cased
    Changes_When_Casefolded Changes_When_Casemapped Changes_When_Lowercased
    Changes_When_Titlecased Changes_When_Uppercased Dash Default_Ignorable_Code_Point
    Deprecated Diacritic Emoji Emoji_Component Emoji_Modifier Emoji_Modifier_Base
    Emoji_Presentation Extended_Pictographic Extender Grapheme_Base Grapheme_Extend
    Hex_Digit Hyphen ID_Continue ID_Start Ideographic IDS_Binary_Operator
    IDS_Trinary_Operator Join_Control Logical_Order_Exception Lowercase Math
    Noncharacter_Code_Point Pattern_Syntax Pattern_White_Space
    Prepended_Concatenation_Mark Quotation_Mark Radical Regional_Indicator
    Sentence_Terminal Soft_Dotted Terminal_Punctuation Unified_Ideograph Uppercase
    Variation_Selector White_Space XID_Continue XID_Start
);
for my $prop (@bin) {
    my @l = eval { prop_invlist($prop) };
    next unless @l;
    my @names = ($prop, eval { prop_aliases($prop) } );
    my %seen;
    my @uniq = grep { defined $_ && !$seen{lc $_}++ } @names;
    emit(join("|", "bool", @uniq), @l);
}

# Simple case folding map: "scf<TAB>cp:folded,cp:folded,..."
{
    my ($cps, $folds) = prop_invmap("Simple_Case_Folding");
    my @pairs;
    for my $i (0 .. $#$cps) {
        my $start = $cps->[$i];
        my $end   = ($i < $#$cps ? $cps->[$i+1] - 1 : 0x10FFFF);
        my $f     = $folds->[$i];
        next if !defined $f || $f eq '0';
        if ($f =~ /^</) { next }   # unmapped marker
        for my $cp ($start .. $end) {
            my $to = ($f =~ /^\d+$/) ? $f + ($cp - $start) : hex($f) + ($cp - $start);
            push @pairs, "$cp:$to" if $to != $cp;
        }
    }
    print "scf\t", join(",", @pairs), "\n";
}
EOF
perl -MUnicode::UCD=prop_invmap tools/dump_ucd.pl > /tmp/ucd.txt 2>/tmp/ucd.err; echo "exit=$?"; head -c 300 /tmp/ucd.err; wc -l /tmp/ucd.txt; wc -c /tmp/ucd.txt; cut -f1 /tmp/ucd.txt | head -20

