//! Unicode character-class data.
//!
//! The tables live in `src/ucd.txt`, which is produced by `tools/dump_ucd.pl`
//! from the Unicode Character Database that ships with Perl.  Each line holds
//! one property value:
//!
//! ```text
//! <tag>|<name>|<alias>...<TAB><inversion list as decimal code points>
//! ```
//!
//! An inversion list alternates "start of a member run" and "start of a
//! non-member run", so it always has an even length after the implicit
//! `0x110000` terminator is appended.
//!
//! Lines are searched on demand: only the handful of properties a pattern
//! actually mentions ever get parsed.

use super::hir::ClassRanges;

const UCD: &str = include_str!("../ucd.txt");

/// Normalizes a Unicode property or value name for loose matching: case is
/// folded and `-`, `_` and spaces are dropped (UAX44-LM3).
fn normalize(name: &str) -> String {
    name.chars()
        .filter(|c| *c != '-' && *c != '_' && *c != ' ')
        .flat_map(|c| c.to_lowercase())
        .collect()
}

/// Looks up a line whose tag is `tag` and which lists `value` among its names.
fn find_line(tag: &str, value: &str) -> Option<&'static str> {
    let wanted = normalize(value);
    for line in UCD.lines() {
        let (key, data) = line.split_once('\t')?;
        let mut names = key.split('|');
        if names.next() != Some(tag) {
            continue;
        }
        if names.any(|n| normalize(n) == wanted) {
            return Some(data);
        }
    }
    None
}

fn parse_invlist(data: &str) -> ClassRanges {
    let mut bounds: Vec<u32> = data
        .split(',')
        .filter(|s| !s.is_empty())
        .map(|s| s.parse().unwrap_or(0))
        .collect();
    if bounds.len() % 2 == 1 {
        bounds.push(0x11_0000);
    }
    let mut ranges = ClassRanges::new();
    for pair in bounds.chunks(2) {
        if pair[1] > pair[0] {
            ranges.push(pair[0], pair[1] - 1);
        }
    }
    ranges.normalize();
    ranges
}

fn table(tag: &str, value: &str) -> Option<ClassRanges> {
    find_line(tag, value).map(parse_invlist)
}

/// Which top-level Unicode property a `\p{...}` query names.
enum Prop {
    GeneralCategory,
    Script,
    ScriptExtensions,
    GraphemeClusterBreak,
    SentenceBreak,
    WordBreak,
    Age,
    /// Recognized by the Unicode standard but not implemented here (matching
    /// the upstream engine, which also rejects these).
    Unsupported,
}

fn canonical_prop(name: &str) -> Option<Prop> {
    match normalize(name).as_str() {
        "gc" | "generalcategory" => Some(Prop::GeneralCategory),
        "sc" | "script" => Some(Prop::Script),
        "scx" | "scriptextensions" => Some(Prop::ScriptExtensions),
        "gcb" | "graphemeclusterbreak" => Some(Prop::GraphemeClusterBreak),
        "sb" | "sentencebreak" => Some(Prop::SentenceBreak),
        "wb" | "wordbreak" => Some(Prop::WordBreak),
        "age" => Some(Prop::Age),
        "blk" | "block" | "bc" | "bidiclass" | "ccc" | "canonicalcombiningclass"
        | "dt" | "decompositiontype" | "ea" | "eastasianwidth" | "hst"
        | "hangulsyllabletype" | "jg" | "joininggroup" | "jt" | "joiningtype"
        | "lb" | "linebreak" | "nfcqc" | "nfdqc" | "nfkcqc" | "nfkdqc" | "nt"
        | "numerictype" | "nv" | "numericvalue" | "vo" | "verticalorientation" => {
            Some(Prop::Unsupported)
        }
        _ => None,
    }
}

/// Result of resolving a property query.
pub enum Lookup {
    Found(ClassRanges),
    PropertyNotFound,
    PropertyValueNotFound,
}

/// Resolves `\p{name=value}`.
pub fn class_by_pair(name: &str, value: &str) -> Lookup {
    let prop = match canonical_prop(name) {
        Some(p) => p,
        None => return Lookup::PropertyNotFound,
    };
    let tag = match prop {
        Prop::GeneralCategory => "gc",
        Prop::Script => "sc",
        Prop::ScriptExtensions => "scx",
        Prop::GraphemeClusterBreak => "GCB",
        Prop::SentenceBreak => "SB",
        Prop::WordBreak => "WB",
        Prop::Age => "age",
        Prop::Unsupported => return Lookup::PropertyValueNotFound,
    };
    if let Prop::GeneralCategory = prop {
        if let Some(r) = gencat(value) {
            return Lookup::Found(r);
        }
        return Lookup::PropertyValueNotFound;
    }
    if let Prop::Age = prop {
        // `age=V` means "assigned in version V or earlier", i.e. the union of
        // every version up to and including V.
        return match age_upto(value) {
            Some(r) => Lookup::Found(r),
            None => Lookup::PropertyValueNotFound,
        };
    }
    match table(tag, value) {
        Some(r) => Lookup::Found(r),
        None => Lookup::PropertyValueNotFound,
    }
}

/// Resolves the single-name form `\p{name}`.
pub fn class_by_name(name: &str) -> Lookup {
    let norm = normalize(name);
    match norm.as_str() {
        "any" => {
            let mut r = ClassRanges::new();
            r.push(0, 0x10_FFFF);
            return Lookup::Found(r);
        }
        "ascii" => {
            let mut r = ClassRanges::new();
            r.push(0, 0x7F);
            return Lookup::Found(r);
        }
        "assigned" => {
            let mut r = gencat("Cn").unwrap_or_default();
            r.negate();
            return Lookup::Found(r);
        }
        _ => {}
    }
    if let Some(r) = table("bool", name) {
        return Lookup::Found(r);
    }
    if let Some(r) = gencat(name) {
        return Lookup::Found(r);
    }
    if let Some(r) = table("sc", name) {
        return Lookup::Found(r);
    }
    Lookup::PropertyNotFound
}

/// Resolves the one-letter form `\pL`, which is always a general category.
pub fn class_by_letter(c: char) -> Lookup {
    match gencat(&c.to_string()) {
        Some(r) => Lookup::Found(r),
        None => Lookup::PropertyNotFound,
    }
}

fn gencat(value: &str) -> Option<ClassRanges> {
    // `Any` is accepted as a general category value too.
    if normalize(value) == "any" {
        let mut r = ClassRanges::new();
        r.push(0, 0x10_FFFF);
        return Some(r);
    }
    table("gc", value)
}

fn age_upto(value: &str) -> Option<ClassRanges> {
    let wanted = normalize(value);
    let mut versions: Vec<(f64, &str)> = Vec::new();
    for line in UCD.lines() {
        let (key, _) = line.split_once('\t')?;
        let mut names = key.split('|');
        if names.next() != Some("age") {
            continue;
        }
        let name = names.next()?;
        if let Ok(v) = name.parse::<f64>() {
            versions.push((v, name));
        }
    }
    let target = versions.iter().find(|(_, n)| normalize(n) == wanted)?.0;
    let mut out = ClassRanges::new();
    for (v, name) in &versions {
        if *v <= target {
            if let Some(r) = table("age", name) {
                out.extend(&r);
            }
        }
    }
    out.normalize();
    Some(out)
}

/// `\w` in Unicode mode.
pub fn perl_word() -> ClassRanges {
    let mut r = table("bool", "Alphabetic").unwrap_or_default();
    for part in ["M", "Nd", "Pc"] {
        if let Some(p) = table("gc", part) {
            r.extend(&p);
        }
    }
    if let Some(p) = table("bool", "Join_Control") {
        r.extend(&p);
    }
    r.normalize();
    r
}

/// `\s` in Unicode mode.
pub fn perl_space() -> ClassRanges {
    table("bool", "White_Space").unwrap_or_default()
}

/// `\d` in Unicode mode.
pub fn perl_digit() -> ClassRanges {
    table("gc", "Nd").unwrap_or_default()
}

// ---------------------------------------------------------------------------
// Simple case folding
// ---------------------------------------------------------------------------

/// Case-folding equivalence classes, indexed by the folded code point.
///
/// `scf` maps a code point to its simple case folding; two code points are
/// case-insensitively equal exactly when their foldings agree.
struct Folder {
    /// `(code point, folded code point)`, sorted by code point.
    to_fold: Vec<(u32, u32)>,
    /// `(folded code point, members)`, sorted by folded code point.
    classes: Vec<(u32, Vec<u32>)>,
}

fn folder() -> &'static Folder {
    use std::sync::OnceLock;
    static FOLDER: OnceLock<Folder> = OnceLock::new();
    FOLDER.get_or_init(|| {
        let mut to_fold: Vec<(u32, u32)> = Vec::new();
        if let Some(data) = find_line_exact("scf") {
            for item in data.split(',') {
                if let Some((a, b)) = item.split_once(':') {
                    if let (Ok(a), Ok(b)) = (a.parse::<u32>(), b.parse::<u32>()) {
                        to_fold.push((a, b));
                    }
                }
            }
        }
        to_fold.sort_unstable();
        let mut buckets: std::collections::BTreeMap<u32, Vec<u32>> =
            std::collections::BTreeMap::new();
        for &(cp, fold) in &to_fold {
            let entry = buckets.entry(fold).or_default();
            if entry.is_empty() {
                entry.push(fold);
            }
            entry.push(cp);
        }
        let mut classes: Vec<(u32, Vec<u32>)> = buckets.into_iter().collect();
        for (_, members) in classes.iter_mut() {
            members.sort_unstable();
            members.dedup();
        }
        Folder { to_fold, classes }
    })
}

fn find_line_exact(tag: &str) -> Option<&'static str> {
    for line in UCD.lines() {
        let (key, data) = line.split_once('\t')?;
        if key == tag {
            return Some(data);
        }
    }
    None
}

fn simple_fold(cp: u32) -> u32 {
    let f = folder();
    match f.to_fold.binary_search_by_key(&cp, |e| e.0) {
        Ok(i) => f.to_fold[i].1,
        Err(_) => cp,
    }
}

/// All code points case-insensitively equal to `cp`, including `cp` itself.
pub fn fold_equivalents(cp: u32) -> Option<&'static [u32]> {
    let f = folder();
    let key = simple_fold(cp);
    match f.classes.binary_search_by_key(&key, |e| e.0) {
        Ok(i) => Some(&f.classes[i].1),
        Err(_) => None,
    }
}

/// Adds the case-folded closure of `ranges` to itself.
pub fn case_fold_ranges(ranges: &ClassRanges) -> ClassRanges {
    let mut out = ranges.clone();
    for &(lo, hi) in ranges.as_slice() {
        // Fold tables only cover cased characters; skip huge uncased spans
        // quickly by walking the range and looking each code point up.
        if hi - lo > 0x2000 {
            // Large ranges are dominated by uncased characters; still walk
            // them, but the lookup is a binary search so this stays cheap.
        }
        for cp in lo..=hi {
            if let Some(members) = fold_equivalents(cp) {
                for &m in members {
                    out.push(m, m);
                }
            }
        }
    }
    out.normalize();
    out
}

