//! The intermediate representation the parser produces and the compiler eats.

/// A sorted, non-overlapping set of code point ranges (inclusive on both ends).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ClassRanges {
    ranges: Vec<(u32, u32)>,
}

impl ClassRanges {
    pub fn new() -> Self {
        ClassRanges { ranges: Vec::new() }
    }

    pub fn single(cp: u32) -> Self {
        ClassRanges {
            ranges: vec![(cp, cp)],
        }
    }

    pub fn push(&mut self, lo: u32, hi: u32) {
        if lo <= hi {
            self.ranges.push((lo, hi));
        }
    }

    pub fn extend(&mut self, other: &ClassRanges) {
        self.ranges.extend_from_slice(&other.ranges);
    }

    pub fn as_slice(&self) -> &[(u32, u32)] {
        &self.ranges
    }

    pub fn is_empty(&self) -> bool {
        self.ranges.is_empty()
    }

    /// Sorts and merges overlapping or adjacent ranges.
    pub fn normalize(&mut self) {
        if self.ranges.is_empty() {
            return;
        }
        self.ranges.sort_unstable();
        let mut out: Vec<(u32, u32)> = Vec::with_capacity(self.ranges.len());
        for &(lo, hi) in &self.ranges {
            match out.last_mut() {
                Some(last) if lo <= last.1.saturating_add(1) => {
                    if hi > last.1 {
                        last.1 = hi;
                    }
                }
                _ => out.push((lo, hi)),
            }
        }
        self.ranges = out;
    }

    /// Replaces the set with its complement over all of Unicode.
    pub fn negate(&mut self) {
        self.normalize();
        let mut out = Vec::with_capacity(self.ranges.len() + 1);
        let mut next = 0u32;
        for &(lo, hi) in &self.ranges {
            if lo > next {
                out.push((next, lo - 1));
            }
            next = hi.saturating_add(1);
            if next > 0x10_FFFF {
                next = 0x11_0000;
            }
        }
        if next <= 0x10_FFFF {
            out.push((next, 0x10_FFFF));
        }
        self.ranges = out;
    }

    pub fn intersect(&self, other: &ClassRanges) -> ClassRanges {
        let mut out = ClassRanges::new();
        let (mut i, mut j) = (0, 0);
        while i < self.ranges.len() && j < other.ranges.len() {
            let a = self.ranges[i];
            let b = other.ranges[j];
            let lo = a.0.max(b.0);
            let hi = a.1.min(b.1);
            if lo <= hi {
                out.push(lo, hi);
            }
            if a.1 < b.1 {
                i += 1;
            } else {
                j += 1;
            }
        }
        out
    }

    /// Set difference: everything in `self` that is not in `other`.
    pub fn difference(&self, other: &ClassRanges) -> ClassRanges {
        let mut neg = other.clone();
        neg.negate();
        self.intersect(&neg)
    }

    pub fn symmetric_difference(&self, other: &ClassRanges) -> ClassRanges {
        let mut out = self.difference(other);
        out.extend(&other.difference(self));
        out.normalize();
        out
    }

    pub fn union(&self, other: &ClassRanges) -> ClassRanges {
        let mut out = self.clone();
        out.extend(other);
        out.normalize();
        out
    }

    pub fn contains(&self, cp: u32) -> bool {
        self.ranges
            .binary_search_by(|&(lo, hi)| {
                if cp < lo {
                    std::cmp::Ordering::Greater
                } else if cp > hi {
                    std::cmp::Ordering::Less
                } else {
                    std::cmp::Ordering::Equal
                }
            })
            .is_ok()
    }

    /// True when the set contains exactly one code point.
    pub fn as_single(&self) -> Option<u32> {
        match self.ranges.as_slice() {
            [(lo, hi)] if lo == hi => Some(*lo),
            _ => None,
        }
    }
}

/// A sorted, non-overlapping set of byte ranges, used when Unicode mode is off.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ByteRanges {
    ranges: Vec<(u8, u8)>,
}

impl ByteRanges {
    pub fn new() -> Self {
        ByteRanges { ranges: Vec::new() }
    }

    pub fn push(&mut self, lo: u8, hi: u8) {
        if lo <= hi {
            self.ranges.push((lo, hi));
        }
    }

    pub fn as_slice(&self) -> &[(u8, u8)] {
        &self.ranges
    }

    pub fn from_class(class: &ClassRanges) -> ByteRanges {
        let mut out = ByteRanges::new();
        for &(lo, hi) in class.as_slice() {
            if lo > 0xFF {
                continue;
            }
            out.push(lo as u8, hi.min(0xFF) as u8);
        }
        out.normalize();
        out
    }

    pub fn normalize(&mut self) {
        if self.ranges.is_empty() {
            return;
        }
        self.ranges.sort_unstable();
        let mut out: Vec<(u8, u8)> = Vec::with_capacity(self.ranges.len());
        for &(lo, hi) in &self.ranges {
            match out.last_mut() {
                Some(last) if lo as u16 <= last.1 as u16 + 1 => {
                    if hi > last.1 {
                        last.1 = hi;
                    }
                }
                _ => out.push((lo, hi)),
            }
        }
        self.ranges = out;
    }

    pub fn bitmap(&self) -> [bool; 256] {
        let mut map = [false; 256];
        for &(lo, hi) in &self.ranges {
            for b in lo..=hi {
                map[b as usize] = true;
            }
        }
        map
    }

    pub fn is_empty(&self) -> bool {
        self.ranges.is_empty()
    }
}

/// Zero-width assertions.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Look {
    StartText,
    EndText,
    StartLine,
    EndLine,
    WordUnicode,
    WordUnicodeNegate,
    WordAscii,
    WordAsciiNegate,
    WordStartUnicode,
    WordEndUnicode,
    WordStartHalfUnicode,
    WordEndHalfUnicode,
    WordStartAscii,
    WordEndAscii,
    WordStartHalfAscii,
    WordEndHalfAscii,
}

#[derive(Clone, Debug)]
pub enum Hir {
    Empty,
    /// A run of bytes that must appear verbatim.
    Literal(Vec<u8>),
    /// One code point drawn from a Unicode set.
    Class(ClassRanges),
    /// One byte drawn from a byte set.
    ByteClass(ByteRanges),
    Look(Look),
    Capture {
        index: u32,
        sub: Box<Hir>,
    },
    Concat(Vec<Hir>),
    Alternation(Vec<Hir>),
    Repeat {
        min: u32,
        max: Option<u32>,
        greedy: bool,
        sub: Box<Hir>,
    },
}

