//! Errors produced while building a regex, rendered the way the pattern
//! compiler reports them on the command line.

use std::fmt;

/// A half-open span of *character* offsets into the pattern.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn new(start: usize, end: usize) -> Span {
        Span { start, end }
    }

    pub fn at(pos: usize) -> Span {
        Span {
            start: pos,
            end: pos + 1,
        }
    }
}

#[derive(Clone, Debug)]
pub enum Error {
    /// A syntax error, shown with the offending part of the pattern underlined.
    Parse {
        message: &'static str,
        pattern: String,
        span: Span,
        aux: Option<Span>,
    },
    /// The compiled program would be too large.
    TooBig(usize),
}

impl Error {
    pub fn parse(
        message: &'static str,
        pattern: &str,
        span: Span,
        aux: Option<Span>,
    ) -> Error {
        Error::Parse {
            message,
            pattern: pattern.to_string(),
            span,
            aux,
        }
    }
}

const DIVIDER_WIDTH: usize = 79;

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::TooBig(limit) => {
                write!(f, "Compiled regex exceeds size limit of {limit} bytes.")
            }
            Error::Parse {
                message,
                pattern,
                span,
                aux,
            } => {
                writeln!(f, "regex parse error:")?;
                let lines: Vec<&str> = pattern.split('\n').collect();
                if lines.len() == 1 {
                    writeln!(f, "    {}", lines[0])?;
                    let mut marks: Vec<Span> = vec![*span];
                    if let Some(a) = aux {
                        marks.push(*a);
                    }
                    writeln!(f, "    {}", caret_line(&marks, 0))?;
                } else {
                    let divider = "~".repeat(DIVIDER_WIDTH);
                    writeln!(f, "{divider}")?;
                    // Character offsets are pattern-wide, so track where each
                    // line starts in order to translate them into columns.
                    let mut line_start = 0usize;
                    for (i, line) in lines.iter().enumerate() {
                        let width = line.chars().count();
                        writeln!(f, "{}: {}", i + 1, line)?;
                        let mut marks = Vec::new();
                        for m in [Some(span), aux.as_ref()].into_iter().flatten() {
                            if m.start >= line_start && m.start <= line_start + width {
                                marks.push(Span::new(
                                    m.start - line_start,
                                    (m.end - line_start).min(width.max(1)),
                                ));
                            }
                        }
                        if !marks.is_empty() {
                            let prefix = format!("{}: ", i + 1).len();
                            writeln!(
                                f,
                                "{}{}",
                                " ".repeat(prefix),
                                caret_line(&marks, 0)
                            )?;
                        }
                        line_start += width + 1;
                    }
                    writeln!(f, "{divider}")?;
                }
                write!(f, "error: {message}")
            }
        }
    }
}

/// Builds the `   ^^^` underline for one or more spans on a single line.
fn caret_line(marks: &[Span], offset: usize) -> String {
    let mut sorted: Vec<Span> = marks.to_vec();
    sorted.sort_by_key(|s| s.start);
    let mut out = String::new();
    let mut col = offset;
    for m in sorted {
        let start = m.start.max(col);
        let width = m.end.saturating_sub(m.start).max(1);
        while col < start {
            out.push(' ');
            col += 1;
        }
        for _ in 0..width {
            out.push('^');
            col += 1;
        }
    }
    out
}

