//! Pattern parser.
//!
//! Recognizes the same syntax as the Rust `regex` crate: no backreferences and
//! no look-around, but with Unicode classes, inline flags, nested character
//! classes and class set operators.  Flags are tracked as parsing proceeds, so
//! the parser emits HIR directly instead of building a separate AST.

use super::error::{Error, Span};
use super::hir::{ByteRanges, ClassRanges, Hir, Look};
use super::unicode::{self, Lookup};

#[derive(Clone, Copy, Debug)]
pub struct Flags {
    pub case_insensitive: bool,
    pub multi_line: bool,
    pub dot_matches_new_line: bool,
    pub swap_greed: bool,
    pub unicode: bool,
    pub ignore_whitespace: bool,
}

impl Default for Flags {
    fn default() -> Self {
        Flags {
            case_insensitive: false,
            multi_line: false,
            dot_matches_new_line: false,
            swap_greed: false,
            unicode: true,
            ignore_whitespace: false,
        }
    }
}

type Result<T> = std::result::Result<T, Error>;

pub struct Parsed {
    pub hir: Hir,
    /// Capture group names in group-index order; `None` for unnamed groups.
    pub capture_names: Vec<Option<String>>,
}

pub struct Parser<'p> {
    pattern: &'p str,
    chars: Vec<char>,
    pos: usize,
    flags: Flags,
    /// Number of capture groups opened so far (group 0 is the whole match).
    groups: u32,
    capture_names: Vec<Option<String>>,
    /// Where each named group was declared, for duplicate reporting.
    name_spans: Vec<(String, Span)>,
}

impl<'p> Parser<'p> {
    pub fn new(pattern: &'p str, flags: Flags) -> Parser<'p> {
        Parser {
            pattern,
            chars: pattern.chars().collect(),
            pos: 0,
            flags,
            groups: 0,
            capture_names: vec![None],
            name_spans: Vec::new(),
        }
    }

    pub fn parse(mut self) -> Result<Parsed> {
        let hir = self.parse_alternation(None)?;
        if self.pos < self.chars.len() {
            // The only way to stop early at the top level is a stray ')'.
            debug_assert_eq!(self.chars[self.pos], ')');
            return Err(self.err("unopened group", Span::at(self.pos), None));
        }
        Ok(Parsed {
            hir,
            capture_names: self.capture_names,
        })
    }

    // -- character helpers -------------------------------------------------

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn eat(&mut self, c: char) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn is_eof(&self) -> bool {
        self.pos >= self.chars.len()
    }

    fn err(&self, message: &'static str, span: Span, aux: Option<Span>) -> Error {
        Error::parse(message, self.pattern, span, aux)
    }

    /// Skips whitespace and `#` comments when the `x` flag is active.
    fn skip_space(&mut self) {
        if !self.flags.ignore_whitespace {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => {
                    self.pos += 1;
                }
                Some('#') => {
                    while let Some(c) = self.peek() {
                        self.pos += 1;
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
    }

    // -- grammar -----------------------------------------------------------

    /// Parses `branch ('|' branch)*`.  `open` is the position of the enclosing
    /// `(` when parsing inside a group.
    fn parse_alternation(&mut self, open: Option<usize>) -> Result<Hir> {
        let mut branches = Vec::new();
        loop {
            branches.push(self.parse_concat(open)?);
            if self.peek() == Some('|') {
                self.pos += 1;
                continue;
            }
            break;
        }
        Ok(if branches.len() == 1 {
            branches.pop().unwrap()
        } else {
            Hir::Alternation(branches)
        })
    }

    fn parse_concat(&mut self, open: Option<usize>) -> Result<Hir> {
        let mut items: Vec<Hir> = Vec::new();
        // Set to true after a `(?flags)` directive: a repetition operator may
        // not be applied to one.
        let mut last_was_flags = false;
        loop {
            self.skip_space();
            let Some(c) = self.peek() else { break };
            match c {
                '|' => break,
                ')' => {
                    if open.is_none() {
                        break;
                    }
                    break;
                }
                '*' | '+' | '?' => {
                    let start = self.pos;
                    self.pos += 1;
                    let (min, max) = match c {
                        '*' => (0, None),
                        '+' => (1, None),
                        _ => (0, Some(1)),
                    };
                    self.apply_repeat(&mut items, last_was_flags, start, min, max)?;
                    last_was_flags = false;
                }
                '{' => {
                    let start = self.pos;
                    // `{` only forms a repetition; there is no literal fallback.
                    let (min, max) = self.parse_counted()?;
                    self.apply_repeat(&mut items, last_was_flags, start, min, max)?;
                    last_was_flags = false;
                }
                '(' => {
                    match self.parse_group()? {
                        GroupResult::Group(hir) => {
                            items.push(hir);
                            last_was_flags = false;
                        }
                        GroupResult::Flags => {
                            last_was_flags = true;
                        }
                    }
                }
                '[' => {
                    let class = self.parse_class()?;
                    items.push(self.class_to_hir(class));
                    last_was_flags = false;
                }
                '.' => {
                    self.pos += 1;
                    items.push(self.dot());
                    last_was_flags = false;
                }
                '^' => {
                    self.pos += 1;
                    items.push(Hir::Look(if self.flags.multi_line {
                        Look::StartLine
                    } else {
                        Look::StartText
                    }));
                    last_was_flags = false;
                }
                '$' => {
                    self.pos += 1;
                    items.push(Hir::Look(if self.flags.multi_line {
                        Look::EndLine
                    } else {
                        Look::EndText
                    }));
                    last_was_flags = false;
                }
                '\\' => {
                    let hir = self.parse_escape_primary()?;
                    items.push(hir);
                    last_was_flags = false;
                }
                _ => {
                    self.pos += 1;
                    items.push(self.literal_char(c));
                    last_was_flags = false;
                }
            }
        }
        Ok(match items.len() {
            0 => Hir::Empty,
            1 => items.pop().unwrap(),
            _ => Hir::Concat(items),
        })
    }

    fn apply_repeat(
        &mut self,
        items: &mut Vec<Hir>,
        last_was_flags: bool,
        op_start: usize,
        min: u32,
        max: Option<u32>,
    ) -> Result<()> {
        if items.is_empty() || last_was_flags {
            return Err(self.err(
                "repetition operator missing expression",
                Span::at(op_start),
                None,
            ));
        }
        let mut greedy = !self.flags.swap_greed;
        self.skip_space();
        if self.peek() == Some('?') {
            self.pos += 1;
            greedy = !greedy;
        }
        let sub = items.pop().unwrap();
        items.push(Hir::Repeat {
            min,
            max,
            greedy,
            sub: Box::new(sub),
        });
        Ok(())
    }

    /// Parses `{n}`, `{n,}` or `{n,m}` starting at the `{`.
    fn parse_counted(&mut self) -> Result<(u32, Option<u32>)> {
        let start = self.pos;
        self.pos += 1; // '{'
        self.skip_space();
        let min = self.parse_decimal()?;
        self.skip_space();
        let max = if self.eat(',') {
            self.skip_space();
            if self.peek() == Some('}') {
                None
            } else {
                let m = self.parse_decimal()?;
                self.skip_space();
                Some(m)
            }
        } else {
            Some(min)
        };
        if !self.eat('}') {
            return Err(self.err(
                "unclosed counted repetition",
                Span::new(start, self.pos.max(start + 1)),
                None,
            ));
        }
        if let Some(m) = max {
            if min > m {
                return Err(self.err(
                    "invalid repetition count range, the start must be <= the end",
                    Span::new(start, self.pos),
                    None,
                ));
            }
        }
        Ok((min, max))
    }

    fn parse_decimal(&mut self) -> Result<u32> {
        let start = self.pos;
        let mut digits = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                digits.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        if digits.is_empty() {
            return Err(self.err(
                "repetition quantifier expects a valid decimal",
                Span::at(start),
                None,
            ));
        }
        match digits.parse::<u32>() {
            Ok(n) => Ok(n),
            Err(_) => Err(self.err(
                "decimal literal exceeds 32 bits",
                Span::new(start, self.pos),
                None,
            )),
        }
    }

    fn dot(&self) -> Hir {
        if self.flags.unicode {
            let mut r = ClassRanges::new();
            if self.flags.dot_matches_new_line {
                r.push(0, 0x10_FFFF);
            } else {
                r.push(0, 0x09);
                r.push(0x0B, 0x10_FFFF);
            }
            Hir::Class(r)
        } else {
            let mut r = ByteRanges::new();
            if self.flags.dot_matches_new_line {
                r.push(0, 0xFF);
            } else {
                r.push(0, 0x09);
                r.push(0x0B, 0xFF);
            }
            Hir::ByteClass(r)
        }
    }

    /// Builds the HIR for a single literal character under the current flags.
    fn literal_char(&self, c: char) -> Hir {
        if self.flags.case_insensitive {
            let mut r = ClassRanges::single(c as u32);
            r = unicode::case_fold_ranges(&r);
            if !self.flags.unicode {
                // Byte mode: only fold within Latin-1 and only for ASCII.
                let mut br = ByteRanges::new();
                for &(lo, hi) in r.as_slice() {
                    if lo <= 0xFF {
                        br.push(lo as u8, hi.min(0xFF) as u8);
                    }
                }
                br.normalize();
                return Hir::ByteClass(br);
            }
            return Hir::Class(r);
        }
        if !self.flags.unicode && (c as u32) > 0x7F {
            // Non-Unicode mode still matches the UTF-8 encoding of the literal.
            let mut buf = [0u8; 4];
            return Hir::Literal(c.encode_utf8(&mut buf).as_bytes().to_vec());
        }
        let mut buf = [0u8; 4];
        Hir::Literal(c.encode_utf8(&mut buf).as_bytes().to_vec())
    }

    fn class_to_hir(&self, class: ClassRanges) -> Hir {
        let class = if self.flags.case_insensitive {
            unicode::case_fold_ranges(&class)
        } else {
            class
        };
        if self.flags.unicode {
            Hir::Class(class)
        } else {
            Hir::ByteClass(ByteRanges::from_class(&class))
        }
    }

    // -- groups ------------------------------------------------------------

    fn parse_group(&mut self) -> Result<GroupResult> {
        let open = self.pos;
        self.pos += 1; // '('
        if self.peek() == Some('?') {
            // Look-around is recognized only so it can be rejected clearly.
            if matches!(self.peek_at(1), Some('=') | Some('!')) {
                return Err(self.err(
                    "look-around, including look-ahead and look-behind, is not supported",
                    Span::new(open, open + 3),
                    None,
                ));
            }
            if self.peek_at(1) == Some('<')
                && matches!(self.peek_at(2), Some('=') | Some('!'))
            {
                return Err(self.err(
                    "look-around, including look-ahead and look-behind, is not supported",
                    Span::new(open, open + 4),
                    None,
                ));
            }
            let named = if self.peek_at(1) == Some('P') && self.peek_at(2) == Some('<') {
                self.pos += 3;
                true
            } else if self.peek_at(1) == Some('<') {
                self.pos += 2;
                true
            } else {
                false
            };
            if named {
                let name = self.parse_capture_name()?;
                let saved = self.flags;
                let index = self.new_capture(Some(name));
                let sub = self.parse_alternation(Some(open))?;
                if !self.eat(')') {
                    return Err(self.err("unclosed group", Span::at(open), None));
                }
                self.flags = saved;
                return Ok(GroupResult::Group(Hir::Capture {
                    index,
                    sub: Box::new(sub),
                }));
            }
            // `(?flags)` or `(?flags:...)`
            let question = self.pos + 1;
            self.pos += 1; // '?'
            if self.is_eof() {
                return Err(self.err("unclosed group", Span::at(open), None));
            }
            let flags = self.parse_flag_set()?;
            match self.bump() {
                Some(')') => {
                    if flags.is_empty() {
                        return Err(self.err(
                            "repetition operator missing expression",
                            Span::at(question - 1),
                            None,
                        ));
                    }
                    self.apply_flags(&flags);
                    return Ok(GroupResult::Flags);
                }
                Some(':') => {
                    let saved = self.flags;
                    self.apply_flags(&flags);
                    let sub = self.parse_alternation(Some(open))?;
                    if !self.eat(')') {
                        return Err(self.err("unclosed group", Span::at(open), None));
                    }
                    self.flags = saved;
                    return Ok(GroupResult::Group(sub));
                }
                _ => return Err(self.err("unclosed group", Span::at(open), None)),
            }
        }
        let saved = self.flags;
        let index = self.new_capture(None);
        let sub = self.parse_alternation(Some(open))?;
        if !self.eat(')') {
            return Err(self.err("unclosed group", Span::at(open), None));
        }
        self.flags = saved;
        Ok(GroupResult::Group(Hir::Capture {
            index,
            sub: Box::new(sub),
        }))
    }

    fn new_capture(&mut self, name: Option<String>) -> u32 {
        self.groups += 1;
        self.capture_names.push(name);
        self.groups
    }

    fn parse_capture_name(&mut self) -> Result<String> {
        let start = self.pos;
        let mut name = String::new();
        loop {
            match self.peek() {
                None => {
                    return Err(self.err(
                        "unclosed capture group name",
                        Span::at(self.pos),
                        None,
                    ))
                }
                Some('>') => {
                    self.pos += 1;
                    break;
                }
                Some(c) => {
                    if name.is_empty() && c.is_ascii_digit() {
                        return Err(self.err(
                            "invalid capture group character",
                            Span::at(self.pos),
                            None,
                        ));
                    }
                    if !is_capture_char(c) {
                        return Err(self.err(
                            "invalid capture group character",
                            Span::at(self.pos),
                            None,
                        ));
                    }
                    name.push(c);
                    self.pos += 1;
                }
            }
        }
        if name.is_empty() {
            return Err(self.err("empty capture group name", Span::at(start), None));
        }
        let span = Span::new(start, start + name.chars().count());
        if let Some((_, first)) = self.name_spans.iter().find(|(n, _)| *n == name) {
            let first = *first;
            return Err(self.err(
                "duplicate capture group name",
                Span::at(span.start),
                Some(Span::at(first.start)),
            ));
        }
        self.name_spans.push((name.clone(), span));
        Ok(name)
    }

    /// Parses the flag list of a `(?...)` group, stopping before `:` or `)`.
    fn parse_flag_set(&mut self) -> Result<Vec<FlagItem>> {
        let mut items: Vec<FlagItem> = Vec::new();
        let mut negating = false;
        let mut neg_pos = 0usize;
        loop {
            let Some(c) = self.peek() else {
                return Err(self.err(
                    "expected flag but got end of regex",
                    Span::at(self.pos),
                    None,
                ));
            };
            match c {
                ':' | ')' => {
                    if negating && items.iter().all(|i| !i.negated) {
                        return Err(self.err(
                            "dangling flag negation operator",
                            Span::at(neg_pos),
                            None,
                        ));
                    }
                    return Ok(items);
                }
                '-' => {
                    if negating {
                        return Err(self.err("duplicate flag", Span::at(self.pos), None));
                    }
                    negating = true;
                    neg_pos = self.pos;
                    self.pos += 1;
                }
                _ => {
                    let kind = match c {
                        'i' => FlagKind::CaseInsensitive,
                        'm' => FlagKind::MultiLine,
                        's' => FlagKind::DotMatchesNewLine,
                        'U' => FlagKind::SwapGreed,
                        'u' => FlagKind::Unicode,
                        'x' => FlagKind::IgnoreWhitespace,
                        _ => {
                            return Err(self.err(
                                "unrecognized flag",
                                Span::at(self.pos),
                                None,
                            ))
                        }
                    };
                    if let Some(prev) = items.iter().find(|i| i.kind == kind) {
                        return Err(self.err(
                            "duplicate flag",
                            Span::at(self.pos),
                            Some(Span::at(prev.pos)),
                        ));
                    }
                    items.push(FlagItem {
                        kind,
                        negated: negating,
                        pos: self.pos,
                    });
                    self.pos += 1;
                }
            }
        }
    }

    fn apply_flags(&mut self, items: &[FlagItem]) {
        for item in items {
            let on = !item.negated;
            match item.kind {
                FlagKind::CaseInsensitive => self.flags.case_insensitive = on,
                FlagKind::MultiLine => self.flags.multi_line = on,
                FlagKind::DotMatchesNewLine => self.flags.dot_matches_new_line = on,
                FlagKind::SwapGreed => self.flags.swap_greed = on,
                FlagKind::Unicode => self.flags.unicode = on,
                FlagKind::IgnoreWhitespace => self.flags.ignore_whitespace = on,
            }
        }
    }

    // -- escapes -----------------------------------------------------------

    /// Parses an escape sequence appearing outside a character class.
    fn parse_escape_primary(&mut self) -> Result<Hir> {
        let start = self.pos;
        match self.parse_escape(start)? {
            Escape::Literal(c) => Ok(self.literal_char(c)),
            Escape::Byte(b) => Ok(Hir::Literal(vec![b])),
            Escape::Class(mut ranges, negated) => {
                if negated {
                    ranges.negate();
                }
                Ok(self.class_to_hir(ranges))
            }
            Escape::Look(look) => Ok(Hir::Look(look)),
        }
    }

    fn parse_escape(&mut self, start: usize) -> Result<Escape> {
        self.pos += 1; // '\'
        let Some(c) = self.bump() else {
            return Err(self.err(
                "incomplete escape sequence, reached end of pattern prematurely",
                Span::at(start),
                None,
            ));
        };
        match c {
            'a' => Ok(Escape::Literal('\x07')),
            'f' => Ok(Escape::Literal('\x0C')),
            't' => Ok(Escape::Literal('\t')),
            'n' => Ok(Escape::Literal('\n')),
            'r' => Ok(Escape::Literal('\r')),
            'v' => Ok(Escape::Literal('\x0B')),
            'A' => Ok(Escape::Look(Look::StartText)),
            'z' => Ok(Escape::Look(Look::EndText)),
            'b' => {
                if self.peek() == Some('{') {
                    return self.parse_special_word_boundary(start);
                }
                Ok(Escape::Look(self.word_look(false)))
            }
            'B' => Ok(Escape::Look(self.word_look(true))),
            '<' => Ok(Escape::Look(if self.flags.unicode {
                Look::WordStartUnicode
            } else {
                Look::WordStartAscii
            })),
            '>' => Ok(Escape::Look(if self.flags.unicode {
                Look::WordEndUnicode
            } else {
                Look::WordEndAscii
            })),
            'd' => Ok(Escape::Class(self.perl_class('d'), false)),
            'D' => Ok(Escape::Class(self.perl_class('d'), true)),
            's' => Ok(Escape::Class(self.perl_class('s'), false)),
            'S' => Ok(Escape::Class(self.perl_class('s'), true)),
            'w' => Ok(Escape::Class(self.perl_class('w'), false)),
            'W' => Ok(Escape::Class(self.perl_class('w'), true)),
            'p' | 'P' => self.parse_unicode_class(start, c == 'P'),
            'x' | 'u' | 'U' => {
                let width = match c {
                    'x' => 2,
                    'u' => 4,
                    _ => 8,
                };
                self.parse_hex(start, width)
            }
            '0'..='9' => Err(self.err(
                "backreferences are not supported",
                Span::new(start, start + 2),
                None,
            )),
            _ if !c.is_alphanumeric() => Ok(Escape::Literal(c)),
            _ => Err(self.err(
                "unrecognized escape sequence",
                Span::new(start, start + 2),
                None,
            )),
        }
    }

    fn word_look(&self, negate: bool) -> Look {
        match (self.flags.unicode, negate) {
            (true, false) => Look::WordUnicode,
            (true, true) => Look::WordUnicodeNegate,
            (false, false) => Look::WordAscii,
            (false, true) => Look::WordAsciiNegate,
        }
    }

    /// Handles `\b{start}`, `\b{end}`, `\b{start-half}` and `\b{end-half}`.
    fn parse_special_word_boundary(&mut self, start: usize) -> Result<Escape> {
        let brace = self.pos;
        self.pos += 1; // '{'
        let mut name = String::new();
        loop {
            match self.peek() {
                None => {
                    return Err(self.err(
                        "found either the beginning of a special word boundary or a \
                         bounded repetition on a \\b with an opening brace, but no \
                         closing brace",
                        Span::new(start, brace + 1),
                        None,
                    ))
                }
                Some('}') => {
                    self.pos += 1;
                    break;
                }
                Some(c) => {
                    name.push(c);
                    self.pos += 1;
                }
            }
        }
        let uni = self.flags.unicode;
        let look = match name.as_str() {
            "start" => {
                if uni {
                    Look::WordStartUnicode
                } else {
                    Look::WordStartAscii
                }
            }
            "end" => {
                if uni {
                    Look::WordEndUnicode
                } else {
                    Look::WordEndAscii
                }
            }
            "start-half" => {
                if uni {
                    Look::WordStartHalfUnicode
                } else {
                    Look::WordStartHalfAscii
                }
            }
            "end-half" => {
                if uni {
                    Look::WordEndHalfUnicode
                } else {
                    Look::WordEndHalfAscii
                }
            }
            _ => {
                return Err(self.err(
                    "invalid word boundary assertion, valid assertions are \\b{start}, \
                     \\b{end}, \\b{start-half} or \\b{end-half}",
                    Span::new(brace + 1, self.pos - 1),
                    None,
                ))
            }
        };
        Ok(Escape::Look(look))
    }

    fn perl_class(&self, which: char) -> ClassRanges {
        if self.flags.unicode {
            match which {
                'd' => unicode::perl_digit(),
                's' => unicode::perl_space(),
                _ => unicode::perl_word(),
            }
        } else {
            let mut r = ClassRanges::new();
            match which {
                'd' => r.push('0' as u32, '9' as u32),
                's' => {
                    r.push(0x09, 0x0D);
                    r.push(0x20, 0x20);
                }
                _ => {
                    r.push('0' as u32, '9' as u32);
                    r.push('A' as u32, 'Z' as u32);
                    r.push('_' as u32, '_' as u32);
                    r.push('a' as u32, 'z' as u32);
                }
            }
            r.normalize();
            r
        }
    }

    fn parse_hex(&mut self, start: usize, width: usize) -> Result<Escape> {
        if self.peek() == Some('{') {
            self.pos += 1;
            let digits_start = self.pos;
            let mut digits = String::new();
            loop {
                match self.peek() {
                    None => {
                        return Err(self.err(
                            "incomplete escape sequence, reached end of pattern prematurely",
                            Span::at(self.pos),
                            None,
                        ))
                    }
                    Some('}') => {
                        self.pos += 1;
                        break;
                    }
                    Some(c) if c.is_ascii_hexdigit() => {
                        digits.push(c);
                        self.pos += 1;
                    }
                    Some(_) => {
                        return Err(self.err(
                            "invalid hexadecimal digit",
                            Span::at(self.pos),
                            None,
                        ))
                    }
                }
            }
            if digits.is_empty() {
                return Err(self.err(
                    "hexadecimal literal empty",
                    Span::new(digits_start - 1, digits_start + 1),
                    None,
                ));
            }
            let value = u32::from_str_radix(&digits, 16).unwrap_or(0x11_0000);
            return self.hex_to_escape(value, digits_start, self.pos - 1);
        }
        let digits_start = self.pos;
        let mut digits = String::new();
        for _ in 0..width {
            match self.peek() {
                Some(c) if c.is_ascii_hexdigit() => {
                    digits.push(c);
                    self.pos += 1;
                }
                None => {
                    return Err(self.err(
                        "incomplete escape sequence, reached end of pattern prematurely",
                        Span::at(self.pos),
                        None,
                    ))
                }
                Some(_) => {
                    return Err(self.err(
                        "invalid hexadecimal digit",
                        Span::at(self.pos),
                        None,
                    ))
                }
            }
        }
        let value = u32::from_str_radix(&digits, 16).unwrap_or(0x11_0000);
        self.hex_to_escape(value, digits_start, self.pos)
    }

    fn hex_to_escape(&self, value: u32, span_start: usize, span_end: usize) -> Result<Escape> {
        match char::from_u32(value) {
            Some(c) => Ok(Escape::Literal(c)),
            None => {
                if !self.flags.unicode && value <= 0xFF {
                    Ok(Escape::Byte(value as u8))
                } else {
                    Err(self.err(
                        "hexadecimal literal is not a Unicode scalar value",
                        Span::new(span_start, span_end),
                        None,
                    ))
                }
            }
        }
    }

    /// Parses `\p{...}`, `\pL`, `\P{...}` and `\PL`.
    fn parse_unicode_class(&mut self, start: usize, negate: bool) -> Result<Escape> {
        let Some(c) = self.peek() else {
            return Err(self.err(
                "incomplete escape sequence, reached end of pattern prematurely",
                Span::at(self.pos),
                None,
            ));
        };
        if c != '{' {
            self.pos += 1;
            let span = Span::new(start, self.pos);
            return match unicode::class_by_letter(c) {
                Lookup::Found(r) => Ok(Escape::Class(r, negate)),
                _ => Err(self.err("Unicode property not found", span, None)),
            };
        }
        self.pos += 1;
        let mut body = String::new();
        loop {
            match self.peek() {
                None => {
                    return Err(self.err(
                        "incomplete escape sequence, reached end of pattern prematurely",
                        Span::at(self.pos),
                        None,
                    ))
                }
                Some('}') => {
                    self.pos += 1;
                    break;
                }
                Some(ch) => {
                    body.push(ch);
                    self.pos += 1;
                }
            }
        }
        let span = Span::new(start, self.pos);
        let lookup = if let Some(idx) = body.find(['=', ':']) {
            let (name, value) = body.split_at(idx);
            unicode::class_by_pair(name, &value[1..])
        } else {
            unicode::class_by_name(&body)
        };
        match lookup {
            Lookup::Found(r) => Ok(Escape::Class(r, negate)),
            Lookup::PropertyNotFound => {
                Err(self.err("Unicode property not found", span, None))
            }
            Lookup::PropertyValueNotFound => {
                Err(self.err("Unicode property value not found", span, None))
            }
        }
    }

    // -- character classes -------------------------------------------------

    /// Parses a bracketed character class starting at `[`.
    fn parse_class(&mut self) -> Result<ClassRanges> {
        let open = self.pos;
        self.pos += 1; // '['
        let negated = self.eat('^');
        // A `]` in leading position is a literal member.
        let mut items = ClassRanges::new();
        let mut leading_bracket = false;
        if self.peek() == Some(']') {
            self.pos += 1;
            items.push(']' as u32, ']' as u32);
            leading_bracket = true;
        }
        let prelude = Span::new(open, self.pos);
        let _ = leading_bracket;

        // Union accumulated so far, plus the pending set operator.
        let mut union = items;
        let mut pending: Option<(SetOp, ClassRanges)> = None;

        loop {
            self.skip_space();
            let Some(c) = self.peek() else {
                return Err(self.err("unclosed character class", prelude, None));
            };
            if c == ']' {
                self.pos += 1;
                break;
            }
            // Set operators
            if let Some(op) = self.peek_set_op() {
                self.pos += 2;
                let lhs = match pending.take() {
                    Some((prev, left)) => prev.apply(&left, &union),
                    None => union,
                };
                pending = Some((op, lhs));
                union = ClassRanges::new();
                continue;
            }
            let member = self.parse_class_item(&prelude)?;
            union.extend(&member);
        }
        let mut result = match pending {
            Some((op, left)) => op.apply(&left, &union),
            None => union,
        };
        result.normalize();
        if negated {
            if self.flags.case_insensitive {
                // Folding happens before negation so that `(?i)[^a]` does not
                // match `A`.
                result = unicode::case_fold_ranges(&result);
            }
            result.negate();
        }
        Ok(result)
    }

    fn peek_set_op(&self) -> Option<SetOp> {
        match (self.peek(), self.peek_at(1)) {
            (Some('&'), Some('&')) => Some(SetOp::Intersection),
            (Some('-'), Some('-')) => Some(SetOp::Difference),
            (Some('~'), Some('~')) => Some(SetOp::SymmetricDifference),
            _ => None,
        }
    }

    /// Parses one member of a character class: a nested class, a POSIX class,
    /// a range, or a single character.
    fn parse_class_item(&mut self, prelude: &Span) -> Result<ClassRanges> {
        if self.peek() == Some('[') {
            if let Some(posix) = self.try_parse_posix()? {
                return Ok(posix);
            }
            return self.parse_class();
        }
        let start = self.pos;
        let lo = self.parse_class_bound(prelude)?;
        // A `-` directly before `]` or before another `-` is a literal.
        if self.peek() == Some('-')
            && self.peek_at(1) != Some(']')
            && self.peek_at(1) != Some('-')
            && self.peek_at(1).is_some()
        {
            let dash = self.pos;
            self.pos += 1;
            if self.peek() == Some('[') {
                // `[a-[b]]` is not a range; the dash stays literal.
                self.pos = dash;
            } else {
                let hi = self.parse_class_bound(prelude)?;
                let (lo_cp, hi_cp) = match (lo.single(), hi.single()) {
                    (Some(a), Some(b)) => (a, b),
                    (None, _) => {
                        return Err(self.err(
                            "invalid range boundary, must be a literal",
                            Span::new(start, dash),
                            None,
                        ))
                    }
                    (_, None) => {
                        return Err(self.err(
                            "invalid range boundary, must be a literal",
                            Span::new(dash + 1, self.pos),
                            None,
                        ))
                    }
                };
                if lo_cp > hi_cp {
                    return Err(self.err(
                        "invalid character class range, the start must be <= the end",
                        Span::new(start, self.pos),
                        None,
                    ));
                }
                let mut r = ClassRanges::new();
                r.push(lo_cp, hi_cp);
                return Ok(r);
            }
        }
        Ok(lo.into_ranges())
    }

    fn parse_class_bound(&mut self, _prelude: &Span) -> Result<Bound> {
        let start = self.pos;
        match self.peek() {
            Some('\\') => match self.parse_escape(start)? {
                Escape::Literal(c) => Ok(Bound::Char(c as u32)),
                Escape::Byte(b) => Ok(Bound::Char(b as u32)),
                Escape::Class(mut r, negated) => {
                    if negated {
                        r.negate();
                    }
                    Ok(Bound::Set(r))
                }
                Escape::Look(_) => Ok(Bound::Set(ClassRanges::new())),
            },
            Some(c) => {
                self.pos += 1;
                Ok(Bound::Char(c as u32))
            }
            None => Err(self.err("unclosed character class", Span::at(start), None)),
        }
    }

    /// Recognizes `[:name:]` and `[:^name:]` at the current position.
    fn try_parse_posix(&mut self) -> Result<Option<ClassRanges>> {
        if self.peek_at(1) != Some(':') {
            return Ok(None);
        }
        // Find the closing `:]` without consuming anything on failure.
        let mut i = self.pos + 2;
        let negated = if self.chars.get(i) == Some(&'^') {
            i += 1;
            true
        } else {
            false
        };
        let name_start = i;
        while let Some(&c) = self.chars.get(i) {
            if c == ':' || c == ']' {
                break;
            }
            i += 1;
        }
        if self.chars.get(i) != Some(&':') || self.chars.get(i + 1) != Some(&']') {
            return Ok(None);
        }
        let name: String = self.chars[name_start..i].iter().collect();
        let Some(mut ranges) = posix_class(&name, self.flags.unicode) else {
            return Ok(None);
        };
        self.pos = i + 2;
        if negated {
            ranges.negate();
        }
        Ok(Some(ranges))
    }
}

enum GroupResult {
    Group(Hir),
    Flags,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum FlagKind {
    CaseInsensitive,
    MultiLine,
    DotMatchesNewLine,
    SwapGreed,
    Unicode,
    IgnoreWhitespace,
}

struct FlagItem {
    kind: FlagKind,
    negated: bool,
    pos: usize,
}

enum Escape {
    Literal(char),
    /// A raw byte that is not a valid scalar value (only legal without `u`).
    Byte(u8),
    Class(ClassRanges, bool),
    Look(Look),
}

enum Bound {
    Char(u32),
    Set(ClassRanges),
}

impl Bound {
    fn single(&self) -> Option<u32> {
        match self {
            Bound::Char(c) => Some(*c),
            Bound::Set(_) => None,
        }
    }

    fn into_ranges(self) -> ClassRanges {
        match self {
            Bound::Char(c) => ClassRanges::single(c),
            Bound::Set(r) => r,
        }
    }
}

#[derive(Clone, Copy)]
enum SetOp {
    Intersection,
    Difference,
    SymmetricDifference,
}

impl SetOp {
    fn apply(self, left: &ClassRanges, right: &ClassRanges) -> ClassRanges {
        let mut l = left.clone();
        l.normalize();
        let mut r = right.clone();
        r.normalize();
        match self {
            SetOp::Intersection => l.intersect(&r),
            SetOp::Difference => l.difference(&r),
            SetOp::SymmetricDifference => l.symmetric_difference(&r),
        }
    }
}

fn is_capture_char(c: char) -> bool {
    c == '_' || c == '.' || c == '[' || c == ']' || c.is_alphanumeric()
}

fn posix_class(name: &str, unicode: bool) -> Option<ClassRanges> {
    let mut r = ClassRanges::new();
    let ascii = |r: &mut ClassRanges, pairs: &[(u32, u32)]| {
        for &(a, b) in pairs {
            r.push(a, b);
        }
    };
    match name {
        "alnum" => {
            if unicode {
                let mut u = unicode::class_by_name("Alphabetic").ranges();
                u.extend(&unicode::class_by_pair("gc", "Nd").ranges());
                u.normalize();
                return Some(u);
            }
            ascii(&mut r, &[(0x30, 0x39), (0x41, 0x5A), (0x61, 0x7A)]);
        }
        "alpha" => {
            if unicode {
                return Some(unicode::class_by_name("Alphabetic").ranges());
            }
            ascii(&mut r, &[(0x41, 0x5A), (0x61, 0x7A)]);
        }
        "ascii" => ascii(&mut r, &[(0x00, 0x7F)]),
        "blank" => {
            if unicode {
                return Some(unicode::class_by_pair("gc", "Zs").ranges().union(&{
                    let mut t = ClassRanges::new();
                    t.push(0x09, 0x09);
                    t
                }));
            }
            ascii(&mut r, &[(0x09, 0x09), (0x20, 0x20)]);
        }
        "cntrl" => {
            if unicode {
                return Some(unicode::class_by_pair("gc", "Cc").ranges());
            }
            ascii(&mut r, &[(0x00, 0x1F), (0x7F, 0x7F)]);
        }
        "digit" => {
            if unicode {
                return Some(unicode::class_by_pair("gc", "Nd").ranges());
            }
            ascii(&mut r, &[(0x30, 0x39)]);
        }
        "graph" => {
            if unicode {
                let mut u = ClassRanges::new();
                u.push(0, 0x10_FFFF);
                let ws = unicode::class_by_name("White_Space").ranges();
                let cc = unicode::class_by_pair("gc", "Cc").ranges();
                let cf = unicode::class_by_pair("gc", "Cf").ranges();
                let cs = unicode::class_by_pair("gc", "Cs").ranges();
                let cn = unicode::class_by_pair("gc", "Cn").ranges();
                let mut bad = ws;
                bad.extend(&cc);
                bad.extend(&cf);
                bad.extend(&cs);
                bad.extend(&cn);
                bad.normalize();
                return Some(u.difference(&bad));
            }
            ascii(&mut r, &[(0x21, 0x7E)]);
        }
        "lower" => {
            if unicode {
                return Some(unicode::class_by_name("Lowercase").ranges());
            }
            ascii(&mut r, &[(0x61, 0x7A)]);
        }
        "print" => {
            if unicode {
                let graph = posix_class("graph", true)?;
                let mut sp = ClassRanges::new();
                sp.push(0x20, 0x20);
                return Some(graph.union(&sp));
            }
            ascii(&mut r, &[(0x20, 0x7E)]);
        }
        "punct" => {
            if unicode {
                let p = unicode::class_by_pair("gc", "P").ranges();
                let s = unicode::class_by_pair("gc", "S").ranges();
                return Some(p.union(&s));
            }
            ascii(
                &mut r,
                &[(0x21, 0x2F), (0x3A, 0x40), (0x5B, 0x60), (0x7B, 0x7E)],
            );
        }
        "space" => {
            if unicode {
                return Some(unicode::class_by_name("White_Space").ranges());
            }
            ascii(&mut r, &[(0x09, 0x0D), (0x20, 0x20)]);
        }
        "upper" => {
            if unicode {
                return Some(unicode::class_by_name("Uppercase").ranges());
            }
            ascii(&mut r, &[(0x41, 0x5A)]);
        }
        "word" => {
            if unicode {
                return Some(unicode::perl_word());
            }
            ascii(
                &mut r,
                &[(0x30, 0x39), (0x41, 0x5A), (0x5F, 0x5F), (0x61, 0x7A)],
            );
        }
        "xdigit" => {
            if unicode {
                return Some(unicode::class_by_name("Hex_Digit").ranges());
            }
            ascii(&mut r, &[(0x30, 0x39), (0x41, 0x46), (0x61, 0x66)]);
        }
        _ => return None,
    }
    r.normalize();
    Some(r)
}

