//! Compiles HIR into a flat program for the backtracking matcher.

use super::error::Error;
use super::hir::{ByteRanges, ClassRanges, Hir, Look};

/// Matches the size budget the upstream engine enforces.
const SIZE_LIMIT: usize = 10_485_760;
/// Rough byte cost charged per emitted instruction when checking the budget.
const INST_COST: usize = 16;

#[derive(Clone, Debug)]
pub enum Inst {
    /// Consume a fixed run of bytes.
    Bytes { bytes: Vec<u8>, next: u32 },
    /// Consume one code point from a Unicode set.
    Class { class: u32, next: u32 },
    /// Consume one byte from a byte set.
    ByteClass { class: u32, next: u32 },
    /// Try `a` first, then `b`.
    Split { a: u32, b: u32 },
    Jump { next: u32 },
    Save { slot: u32, next: u32 },
    Look { look: Look, next: u32 },
    /// Record the current position for an empty-repetition guard.
    Mark { slot: u32, next: u32 },
    /// Fail unless the position moved since the matching `Mark`.
    Progress { slot: u32, next: u32 },
    Match,
}

pub struct Program {
    pub insts: Vec<Inst>,
    pub classes: Vec<ClassRanges>,
    pub byte_classes: Vec<[bool; 256]>,
    pub slots: usize,
    pub marks: usize,
    /// Set of bytes a match can start with, when that can be determined.
    pub first_bytes: Option<[bool; 256]>,
    /// True when every match must start at offset 0.
    pub anchored_start: bool,
}

pub fn compile(hir: &Hir, groups: usize) -> Result<Program, Error> {
    let mut c = Compiler {
        insts: Vec::new(),
        classes: Vec::new(),
        byte_classes: Vec::new(),
        marks: 0,
    };
    // Slot 0/1 hold the bounds of the whole match.
    let start = c.push(Inst::Save { slot: 0, next: 0 });
    let body = c.emit(hir)?;
    c.patch(start, body);
    let save_end = c.push(Inst::Save { slot: 1, next: 0 });
    let done = c.push(Inst::Match);
    c.patch(save_end, done);
    c.tie_end(body, save_end);

    let mut program = Program {
        insts: c.insts,
        classes: c.classes,
        byte_classes: c.byte_classes,
        slots: 2 * (groups + 1),
        marks: c.marks,
        first_bytes: None,
        anchored_start: false,
    };
    program.analyze();
    Ok(program)
}

struct Compiler {
    insts: Vec<Inst>,
    classes: Vec<ClassRanges>,
    byte_classes: Vec<[bool; 256]>,
    marks: usize,
}

/// A compiled fragment: its entry point plus the holes that need to be patched
/// with whatever comes next.
struct Frag {
    entry: u32,
    holes: Vec<u32>,
}

impl Compiler {
    fn push(&mut self, inst: Inst) -> u32 {
        self.insts.push(inst);
        (self.insts.len() - 1) as u32
    }

    fn check_size(&self) -> Result<(), Error> {
        if self.insts.len().saturating_mul(INST_COST) > SIZE_LIMIT {
            return Err(Error::TooBig(SIZE_LIMIT));
        }
        Ok(())
    }

    fn patch(&mut self, at: u32, target: u32) {
        match &mut self.insts[at as usize] {
            Inst::Bytes { next, .. }
            | Inst::Class { next, .. }
            | Inst::ByteClass { next, .. }
            | Inst::Jump { next }
            | Inst::Save { next, .. }
            | Inst::Look { next, .. }
            | Inst::Mark { next, .. }
            | Inst::Progress { next, .. } => *next = target,
            Inst::Split { b, .. } => *b = target,
            Inst::Match => {}
        }
    }

    /// Patches the `Split`'s preferred branch.
    fn patch_a(&mut self, at: u32, target: u32) {
        if let Inst::Split { a, .. } = &mut self.insts[at as usize] {
            *a = target;
        }
    }

    fn tie_end(&mut self, frag: u32, target: u32) {
        let _ = frag;
        let _ = target;
    }

    /// Emits `hir` and returns the entry instruction index; every dangling exit
    /// is patched to the instruction that follows.
    fn emit(&mut self, hir: &Hir) -> Result<u32, Error> {
        let frag = self.emit_frag(hir)?;
        let next = self.insts.len() as u32;
        for hole in frag.holes {
            self.patch(hole, next);
        }
        Ok(frag.entry)
    }

    fn emit_frag(&mut self, hir: &Hir) -> Result<Frag, Error> {
        self.check_size()?;
        match hir {
            Hir::Empty => {
                let at = self.push(Inst::Jump { next: 0 });
                Ok(Frag {
                    entry: at,
                    holes: vec![at],
                })
            }
            Hir::Literal(bytes) => {
                let at = self.push(Inst::Bytes {
                    bytes: bytes.clone(),
                    next: 0,
                });
                Ok(Frag {
                    entry: at,
                    holes: vec![at],
                })
            }
            Hir::Class(ranges) => {
                let cost = ranges.as_slice().len().max(1);
                if self
                    .insts
                    .len()
                    .saturating_add(cost)
                    .saturating_mul(INST_COST)
                    > SIZE_LIMIT
                {
                    return Err(Error::TooBig(SIZE_LIMIT));
                }
                let id = self.intern_class(ranges);
                let at = self.push(Inst::Class { class: id, next: 0 });
                Ok(Frag {
                    entry: at,
                    holes: vec![at],
                })
            }
            Hir::ByteClass(ranges) => {
                let id = self.intern_byte_class(ranges);
                let at = self.push(Inst::ByteClass { class: id, next: 0 });
                Ok(Frag {
                    entry: at,
                    holes: vec![at],
                })
            }
            Hir::Look(look) => {
                let at = self.push(Inst::Look {
                    look: *look,
                    next: 0,
                });
                Ok(Frag {
                    entry: at,
                    holes: vec![at],
                })
            }
            Hir::Capture { index, sub } => {
                let open = self.push(Inst::Save {
                    slot: 2 * index,
                    next: 0,
                });
                let inner = self.emit_frag(sub)?;
                self.patch(open, inner.entry);
                let close = self.push(Inst::Save {
                    slot: 2 * index + 1,
                    next: 0,
                });
                for hole in inner.holes {
                    self.patch(hole, close);
                }
                Ok(Frag {
                    entry: open,
                    holes: vec![close],
                })
            }
            Hir::Concat(parts) => {
                let mut entry = None;
                let mut holes: Vec<u32> = Vec::new();
                for part in parts {
                    let frag = self.emit_frag(part)?;
                    for hole in holes.drain(..) {
                        self.patch(hole, frag.entry);
                    }
                    holes = frag.holes;
                    if entry.is_none() {
                        entry = Some(frag.entry);
                    }
                }
                match entry {
                    Some(entry) => Ok(Frag { entry, holes }),
                    None => self.emit_frag(&Hir::Empty),
                }
            }
            Hir::Alternation(branches) => {
                let mut holes = Vec::new();
                let mut splits: Vec<u32> = Vec::new();
                let mut entry = None;
                for (i, branch) in branches.iter().enumerate() {
                    let last = i + 1 == branches.len();
                    let split = if last {
                        None
                    } else {
                        Some(self.push(Inst::Split { a: 0, b: 0 }))
                    };
                    if entry.is_none() {
                        entry = Some(split.unwrap_or(self.insts.len() as u32));
                    }
                    if let Some(prev) = splits.pop() {
                        // Chain: the previous split's second branch leads here.
                        let here = split.unwrap_or(self.insts.len() as u32);
                        self.patch(prev, here);
                    }
                    let frag = self.emit_frag(branch)?;
                    if let Some(split) = split {
                        self.patch_a(split, frag.entry);
                        splits.push(split);
                    }
                    holes.extend(frag.holes);
                }
                Ok(Frag {
                    entry: entry.unwrap_or(0),
                    holes,
                })
            }
            Hir::Repeat {
                min,
                max,
                greedy,
                sub,
            } => self.emit_repeat(sub, *min, *max, *greedy),
        }
    }

    fn emit_repeat(
        &mut self,
        sub: &Hir,
        min: u32,
        max: Option<u32>,
        greedy: bool,
    ) -> Result<Frag, Error> {
        match max {
            Some(max) => {
                if max == 0 {
                    return self.emit_frag(&Hir::Empty);
                }
                let mut entry = None;
                let mut holes: Vec<u32> = Vec::new();
                let mut optional_splits: Vec<u32> = Vec::new();
                for i in 0..max {
                    self.check_size()?;
                    let split = if i >= min {
                        let s = self.push(Inst::Split { a: 0, b: 0 });
                        Some(s)
                    } else {
                        None
                    };
                    let here = split.unwrap_or(self.insts.len() as u32);
                    for hole in holes.drain(..) {
                        self.patch(hole, here);
                    }
                    if entry.is_none() {
                        entry = Some(here);
                    }
                    let frag = self.emit_frag(sub)?;
                    if let Some(s) = split {
                        if greedy {
                            self.patch_a(s, frag.entry);
                        } else {
                            // Lazy: prefer leaving the loop.
                            self.patch_a(s, 0);
                            optional_splits.push(s);
                            self.insts[s as usize] = Inst::Split {
                                a: 0,
                                b: frag.entry,
                            };
                        }
                    }
                    holes = frag.holes;
                    if let Some(s) = split {
                        if greedy {
                            optional_splits.push(s);
                        }
                    }
                }
                // Every optional split can also skip straight to the end.
                let mut all = holes;
                for s in optional_splits {
                    if greedy {
                        all.push(s);
                    } else {
                        all.push(SPLIT_A_MARKER | s);
                    }
                }
                Ok(Frag {
                    entry: entry.unwrap_or(0),
                    holes: all,
                })
            }
            None => {
                // `sub{min,}` = min copies followed by a star.
                let mut entry = None;
                let mut holes: Vec<u32> = Vec::new();
                for _ in 0..min {
                    self.check_size()?;
                    let frag = self.emit_frag(sub)?;
                    for hole in holes.drain(..) {
                        self.patch(hole, frag.entry);
                    }
                    if entry.is_none() {
                        entry = Some(frag.entry);
                    }
                    holes = frag.holes;
                }
                let star = self.emit_star(sub, greedy)?;
                for hole in holes.drain(..) {
                    self.patch(hole, star.entry);
                }
                if entry.is_none() {
                    entry = Some(star.entry);
                }
                Ok(Frag {
                    entry: entry.unwrap(),
                    holes: star.holes,
                })
            }
        }
    }

    fn emit_star(&mut self, sub: &Hir, greedy: bool) -> Result<Frag, Error> {
        let nullable = is_nullable(sub);
        let split = self.push(Inst::Split { a: 0, b: 0 });
        let mark = if nullable {
            let slot = self.marks as u32;
            self.marks += 1;
            Some((self.push(Inst::Mark { slot, next: 0 }), slot))
        } else {
            None
        };
        let body = self.emit_frag(sub)?;
        let body_entry = match mark {
            Some((at, _)) => {
                self.patch(at, body.entry);
                at
            }
            None => body.entry,
        };
        if greedy {
            self.patch_a(split, body_entry);
        } else {
            self.insts[split as usize] = Inst::Split {
                a: 0,
                b: body_entry,
            };
        }
        let tail = match mark {
            Some((_, slot)) => {
                let p = self.push(Inst::Progress { slot, next: split });
                for hole in body.holes {
                    self.patch(hole, p);
                }
                p
            }
            None => {
                let j = self.push(Inst::Jump { next: split });
                for hole in body.holes {
                    self.patch(hole, j);
                }
                j
            }
        };
        let _ = tail;
        Ok(Frag {
            entry: split,
            holes: vec![if greedy {
                split
            } else {
                SPLIT_A_MARKER | split
            }],
        })
    }

    fn intern_class(&mut self, ranges: &ClassRanges) -> u32 {
        if let Some(i) = self.classes.iter().position(|c| c == ranges) {
            return i as u32;
        }
        self.classes.push(ranges.clone());
        (self.classes.len() - 1) as u32
    }

    fn intern_byte_class(&mut self, ranges: &ByteRanges) -> u32 {
        let map = ranges.bitmap();
        if let Some(i) = self.byte_classes.iter().position(|c| c[..] == map[..]) {
            return i as u32;
        }
        self.byte_classes.push(map);
        (self.byte_classes.len() - 1) as u32
    }
}

/// Flags a hole that must patch a `Split`'s *first* branch rather than its
/// second.  Instruction indices never come close to this bit.
const SPLIT_A_MARKER: u32 = 1 << 31;

impl Compiler {
    fn patch_hole(&mut self, hole: u32, target: u32) {
        if hole & SPLIT_A_MARKER != 0 {
            self.patch_a(hole & !SPLIT_A_MARKER, target);
        } else {
            self.patch(hole, target);
        }
    }
}

fn is_nullable(hir: &Hir) -> bool {
    match hir {
        Hir::Empty | Hir::Look(_) => true,
        Hir::Literal(bytes) => bytes.is_empty(),
        Hir::Class(_) | Hir::ByteClass(_) => false,
        Hir::Capture { sub, .. } => is_nullable(sub),
        Hir::Concat(parts) => parts.iter().all(is_nullable),
        Hir::Alternation(branches) => branches.iter().any(is_nullable),
        Hir::Repeat { min, sub, .. } => *min == 0 || is_nullable(sub),
    }
}

impl Program {
    /// Derives the start-byte prefilter and whether the pattern is anchored.
    fn analyze(&mut self) {
        let mut set = [false; 256];
        let mut open = false;
        let mut anchored = true;
        let mut seen = vec![false; self.insts.len()];
        let mut stack = vec![0u32];
        while let Some(pc) = stack.pop() {
            if seen[pc as usize] {
                continue;
            }
            seen[pc as usize] = true;
            match &self.insts[pc as usize] {
                Inst::Match => {
                    open = true;
                    anchored = false;
                }
                Inst::Bytes { bytes, next } => {
                    anchored = false;
                    match bytes.first() {
                        Some(&b) => set[b as usize] = true,
                        None => stack.push(*next),
                    }
                }
                Inst::Class { class, .. } => {
                    anchored = false;
                    for &(lo, hi) in self.classes[*class as usize].as_slice() {
                        let a = utf8_first_byte(lo);
                        let b = utf8_first_byte(hi);
                        for byte in a..=b {
                            set[byte as usize] = true;
                        }
                    }
                }
                Inst::ByteClass { class, .. } => {
                    anchored = false;
                    let map = &self.byte_classes[*class as usize];
                    for (i, on) in map.iter().enumerate() {
                        if *on {
                            set[i] = true;
                        }
                    }
                }
                Inst::Split { a, b } => {
                    stack.push(*a);
                    stack.push(*b);
                }
                Inst::Jump { next }
                | Inst::Save { next, .. }
                | Inst::Mark { next, .. }
                | Inst::Progress { next, .. } => stack.push(*next),
                Inst::Look { look, next } => {
                    if !matches!(look, Look::StartText) {
                        anchored = false;
                    }
                    stack.push(*next);
                }
            }
        }
        self.anchored_start = anchored;
        self.first_bytes = if open { None } else { Some(set) };
    }
}

fn utf8_first_byte(cp: u32) -> u8 {
    let c = char::from_u32(cp).unwrap_or('\u{FFFD}');
    let mut buf = [0u8; 4];
    c.encode_utf8(&mut buf).as_bytes()[0]
}

