//! Compiles HIR into a flat program for the backtracking matcher.
//!
//! Fragments are emitted back-to-front: every `emit` call is told which
//! instruction to continue with, so no patch-up pass is needed.

use super::error::Error;
use super::hir::{ByteRanges, ClassRanges, Hir, Look};

/// Matches the size budget the upstream engine enforces.
const SIZE_LIMIT: usize = 10_485_760;
/// Rough byte cost charged per emitted instruction when checking the budget.
const INST_COST: usize = 16;

#[derive(Clone, Debug)]
pub enum Inst {
    /// Consume a fixed run of bytes.
    Bytes { bytes: Vec<u8>, next: u32 },
    /// Consume one code point drawn from a Unicode set.
    Class { class: u32, next: u32 },
    /// Consume one byte drawn from a byte set.
    ByteClass { class: u32, next: u32 },
    /// Try `a` first, fall back to `b`.
    Split { a: u32, b: u32 },
    Save { slot: u32, next: u32 },
    Look { look: Look, next: u32 },
    /// Record the current position for an empty-repetition guard.
    Mark { slot: u32, next: u32 },
    /// Fail unless the position moved since the matching `Mark`.
    Progress { slot: u32, next: u32 },
    Match,
}

pub struct Program {
    pub insts: Vec<Inst>,
    pub classes: Vec<ClassRanges>,
    pub byte_classes: Vec<[bool; 256]>,
    pub start: u32,
    pub slots: usize,
    pub marks: usize,
    /// Bytes a match can start with, when that set can be determined.
    pub first_bytes: Option<[bool; 256]>,
    /// True when every match must start at offset 0.
    pub anchored_start: bool,
}

pub fn compile(hir: &Hir, groups: usize) -> Result<Program, Error> {
    let mut c = Compiler {
        insts: Vec::new(),
        classes: Vec::new(),
        byte_classes: Vec::new(),
        marks: 0,
    };
    let done = c.push(Inst::Match);
    let end = c.push(Inst::Save { slot: 1, next: done });
    let body = c.emit(hir, end)?;
    let start = c.push(Inst::Save { slot: 0, next: body });

    let mut program = Program {
        insts: c.insts,
        classes: c.classes,
        byte_classes: c.byte_classes,
        start,
        slots: 2 * (groups + 1),
        marks: c.marks,
        first_bytes: None,
        anchored_start: false,
    };
    program.analyze();
    Ok(program)
}

struct Compiler {
    insts: Vec<Inst>,
    classes: Vec<ClassRanges>,
    byte_classes: Vec<[bool; 256]>,
    marks: usize,
}

impl Compiler {
    fn push(&mut self, inst: Inst) -> u32 {
        self.insts.push(inst);
        (self.insts.len() - 1) as u32
    }

    fn budget(&self, extra: usize) -> Result<(), Error> {
        if self
            .insts
            .len()
            .saturating_add(extra)
            .saturating_mul(INST_COST)
            > SIZE_LIMIT
        {
            return Err(Error::TooBig(SIZE_LIMIT));
        }
        Ok(())
    }

    fn emit(&mut self, hir: &Hir, next: u32) -> Result<u32, Error> {
        self.budget(0)?;
        match hir {
            Hir::Empty => Ok(next),
            Hir::Literal(bytes) => {
                if bytes.is_empty() {
                    return Ok(next);
                }
                Ok(self.push(Inst::Bytes {
                    bytes: bytes.clone(),
                    next,
                }))
            }
            Hir::Class(ranges) => {
                // Large classes cost more in the reference engine, which
                // expands them into a UTF-8 automaton.
                self.budget(ranges.as_slice().len())?;
                let class = self.intern_class(ranges);
                Ok(self.push(Inst::Class { class, next }))
            }
            Hir::ByteClass(ranges) => {
                let class = self.intern_byte_class(ranges);
                Ok(self.push(Inst::ByteClass { class, next }))
            }
            Hir::Look(look) => Ok(self.push(Inst::Look { look: *look, next })),
            Hir::Capture { index, sub } => {
                let close = self.push(Inst::Save {
                    slot: 2 * index + 1,
                    next,
                });
                let inner = self.emit(sub, close)?;
                Ok(self.push(Inst::Save {
                    slot: 2 * index,
                    next: inner,
                }))
            }
            Hir::Concat(parts) => {
                let mut cont = next;
                for part in parts.iter().rev() {
                    cont = self.emit(part, cont)?;
                }
                Ok(cont)
            }
            Hir::Alternation(branches) => {
                let mut chain = None;
                for branch in branches.iter().rev() {
                    let entry = self.emit(branch, next)?;
                    chain = Some(match chain {
                        None => entry,
                        Some(rest) => self.push(Inst::Split { a: entry, b: rest }),
                    });
                }
                Ok(chain.unwrap_or(next))
            }
            Hir::Repeat {
                min,
                max,
                greedy,
                sub,
            } => self.emit_repeat(sub, *min, *max, *greedy, next),
        }
    }

    fn emit_repeat(
        &mut self,
        sub: &Hir,
        min: u32,
        max: Option<u32>,
        greedy: bool,
        next: u32,
    ) -> Result<u32, Error> {
        let mut cont = match max {
            Some(max) => {
                if max == 0 {
                    return Ok(next);
                }
                let mut cont = next;
                for _ in 0..(max - min) {
                    self.budget(0)?;
                    let body = self.emit(sub, cont)?;
                    cont = self.push(if greedy {
                        Inst::Split { a: body, b: next }
                    } else {
                        Inst::Split { a: next, b: body }
                    });
                }
                cont
            }
            None => self.emit_star(sub, greedy, next)?,
        };
        for _ in 0..min {
            self.budget(0)?;
            cont = self.emit(sub, cont)?;
        }
        Ok(cont)
    }

    /// Emits `sub*`, guarding against bodies that can match the empty string.
    fn emit_star(&mut self, sub: &Hir, greedy: bool, next: u32) -> Result<u32, Error> {
        // The split is emitted first so the body can jump back to it, then
        // rewritten once the body's entry point is known.
        let split = self.push(Inst::Split { a: 0, b: 0 });
        let entry = if is_nullable(sub) {
            let slot = self.marks as u32;
            self.marks += 1;
            let progress = self.push(Inst::Progress { slot, next: split });
            let body = self.emit(sub, progress)?;
            self.push(Inst::Mark { slot, next: body })
        } else {
            self.emit(sub, split)?
        };
        self.insts[split as usize] = if greedy {
            Inst::Split { a: entry, b: next }
        } else {
            Inst::Split { a: next, b: entry }
        };
        Ok(split)
    }

    fn intern_class(&mut self, ranges: &ClassRanges) -> u32 {
        if let Some(i) = self.classes.iter().position(|c| c == ranges) {
            return i as u32;
        }
        self.classes.push(ranges.clone());
        (self.classes.len() - 1) as u32
    }

    fn intern_byte_class(&mut self, ranges: &ByteRanges) -> u32 {
        let map = ranges.bitmap();
        if let Some(i) = self.byte_classes.iter().position(|c| c[..] == map[..]) {
            return i as u32;
        }
        self.byte_classes.push(map);
        (self.byte_classes.len() - 1) as u32
    }
}

fn is_nullable(hir: &Hir) -> bool {
    match hir {
        Hir::Empty | Hir::Look(_) => true,
        Hir::Literal(bytes) => bytes.is_empty(),
        Hir::Class(_) | Hir::ByteClass(_) => false,
        Hir::Capture { sub, .. } => is_nullable(sub),
        Hir::Concat(parts) => parts.iter().all(is_nullable),
        Hir::Alternation(branches) => branches.iter().any(is_nullable),
        Hir::Repeat { min, sub, .. } => *min == 0 || is_nullable(sub),
    }
}

impl Program {
    /// Derives the start-byte prefilter and whether the pattern is anchored.
    fn analyze(&mut self) {
        let mut set = [false; 256];
        let mut any = false;
        let mut anchored = true;
        let mut seen = vec![false; self.insts.len()];
        let mut stack = vec![self.start];
        while let Some(pc) = stack.pop() {
            if seen[pc as usize] {
                continue;
            }
            seen[pc as usize] = true;
            match &self.insts[pc as usize] {
                Inst::Match => {
                    any = true;
                    anchored = false;
                }
                Inst::Bytes { bytes, next } => {
                    anchored = false;
                    match bytes.first() {
                        Some(&b) => set[b as usize] = true,
                        None => stack.push(*next),
                    }
                }
                Inst::Class { class, .. } => {
                    anchored = false;
                    for &(lo, hi) in self.classes[*class as usize].as_slice() {
                        for byte in utf8_first_byte(lo)..=utf8_first_byte(hi) {
                            set[byte as usize] = true;
                        }
                    }
                }
                Inst::ByteClass { class, .. } => {
                    anchored = false;
                    for (i, on) in self.byte_classes[*class as usize].iter().enumerate() {
                        if *on {
                            set[i] = true;
                        }
                    }
                }
                Inst::Split { a, b } => {
                    stack.push(*a);
                    stack.push(*b);
                }
                Inst::Save { next, .. }
                | Inst::Mark { next, .. }
                | Inst::Progress { next, .. } => stack.push(*next),
                Inst::Look { look, next } => {
                    if !matches!(look, Look::StartText) {
                        anchored = false;
                    }
                    stack.push(*next);
                }
            }
        }
        self.anchored_start = anchored;
        self.first_bytes = if any { None } else { Some(set) };
    }
}

fn utf8_first_byte(cp: u32) -> u8 {
    let c = char::from_u32(cp).unwrap_or('\u{FFFD}');
    let mut buf = [0u8; 4];
    c.encode_utf8(&mut buf).as_bytes()[0]
}

