//! Backtracking matcher.
//!
//! Alternatives are explored in priority order, so the first match found is the
//! leftmost-first one — the same preference order the Rust `regex` crate uses.
//! Backtracking state lives on an explicit stack so that deeply nested
//! repetitions cannot overflow the call stack.

use super::hir::Look;
use super::program::{Inst, Program};
use super::unicode;

/// A pending decision on the backtracking stack.
enum Job {
    /// Resume execution at `pc` with the input cursor at `pos`.
    Run { pc: u32, pos: usize },
    /// Undo a capture slot write.
    Capture { slot: u32, value: Option<usize> },
    /// Undo an empty-repetition mark.
    Mark { slot: u32, value: usize },
}

pub struct Matcher<'p> {
    program: &'p Program,
    stack: Vec<Job>,
    marks: Vec<usize>,
    word: WordTable,
}

/// Caches the Unicode word-character set used by `\b` and friends.
struct WordTable {
    ascii: [bool; 128],
    unicode: super::hir::ClassRanges,
}

impl WordTable {
    fn new() -> WordTable {
        let mut ascii = [false; 128];
        for (i, slot) in ascii.iter_mut().enumerate() {
            let c = i as u8;
            *slot = c.is_ascii_alphanumeric() || c == b'_';
        }
        WordTable {
            ascii,
            unicode: unicode::perl_word(),
        }
    }

    fn is_word_char(&self, c: char) -> bool {
        let cp = c as u32;
        if cp < 128 {
            self.ascii[cp as usize]
        } else {
            self.unicode.contains(cp)
        }
    }

    fn is_word_byte(&self, b: u8) -> bool {
        b < 128 && self.ascii[b as usize]
    }
}

impl<'p> Matcher<'p> {
    pub fn new(program: &'p Program) -> Matcher<'p> {
        Matcher {
            program,
            stack: Vec::new(),
            marks: vec![usize::MAX; program.marks],
            word: WordTable::new(),
        }
    }

    /// Finds the leftmost match at or after `at`, filling `slots`.
    pub fn find_at(
        &mut self,
        hay: &[u8],
        at: usize,
        slots: &mut [Option<usize>],
    ) -> Option<(usize, usize)> {
        let mut start = at;
        loop {
            if start > hay.len() {
                return None;
            }
            if let Some(set) = &self.program.first_bytes {
                // Skip start positions that cannot begin a match.
                while start < hay.len() && !set[hay[start] as usize] {
                    start += 1;
                }
                if start >= hay.len() && !set_allows_eof(set) {
                    // A non-empty match needs at least one byte.
                    if start > hay.len() {
                        return None;
                    }
                }
            }
            for slot in slots.iter_mut() {
                *slot = None;
            }
            if self.run(hay, start, slots) {
                let s = slots[0]?;
                let e = slots[1]?;
                return Some((s, e));
            }
            if self.program.anchored_start && start >= at {
                // `\A` can only match where it already failed.
                return None;
            }
            if start == hay.len() {
                return None;
            }
            start += 1;
        }
    }

    fn run(&mut self, hay: &[u8], start: usize, slots: &mut [Option<usize>]) -> bool {
        self.stack.clear();
        for m in self.marks.iter_mut() {
            *m = usize::MAX;
        }
        self.stack.push(Job::Run {
            pc: self.program.start,
            pos: start,
        });
        while let Some(job) = self.stack.pop() {
            match job {
                Job::Capture { slot, value } => slots[slot as usize] = value,
                Job::Mark { slot, value } => self.marks[slot as usize] = value,
                Job::Run { pc, pos } => {
                    if self.step(hay, pc, pos, slots) {
                        return true;
                    }
                }
            }
        }
        false
    }

    /// Runs forward from `(pc, pos)` until the thread matches or dies.
    fn step(
        &mut self,
        hay: &[u8],
        mut pc: u32,
        mut pos: usize,
        slots: &mut [Option<usize>],
    ) -> bool {
        loop {
            match &self.program.insts[pc as usize] {
                Inst::Match => return true,
                Inst::Bytes { bytes, next } => {
                    if hay.len() - pos >= bytes.len() && hay[pos..pos + bytes.len()] == bytes[..] {
                        pos += bytes.len();
                        pc = *next;
                    } else {
                        return false;
                    }
                }
                Inst::Class { class, next } => {
                    let Some((c, len)) = decode_utf8(hay, pos) else {
                        return false;
                    };
                    if self.program.classes[*class as usize].contains(c as u32) {
                        pos += len;
                        pc = *next;
                    } else {
                        return false;
                    }
                }
                Inst::ByteClass { class, next } => {
                    if pos < hay.len()
                        && self.program.byte_classes[*class as usize][hay[pos] as usize]
                    {
                        pos += 1;
                        pc = *next;
                    } else {
                        return false;
                    }
                }
                Inst::Split { a, b } => {
                    self.stack.push(Job::Run { pc: *b, pos });
                    pc = *a;
                }
                Inst::Save { slot, next } => {
                    let slot = *slot as usize;
                    if slot < slots.len() {
                        self.stack.push(Job::Capture {
                            slot: slot as u32,
                            value: slots[slot],
                        });
                        slots[slot] = Some(pos);
                    }
                    pc = *next;
                }
                Inst::Look { look, next } => {
                    if self.look_matches(*look, hay, pos) {
                        pc = *next;
                    } else {
                        return false;
                    }
                }
                Inst::Mark { slot, next } => {
                    let slot = *slot as usize;
                    self.stack.push(Job::Mark {
                        slot: slot as u32,
                        value: self.marks[slot],
                    });
                    self.marks[slot] = pos;
                    pc = *next;
                }
                Inst::Progress { slot, next } => {
                    if self.marks[*slot as usize] == pos {
                        return false;
                    }
                    pc = *next;
                }
            }
        }
    }

    fn look_matches(&self, look: Look, hay: &[u8], pos: usize) -> bool {
        match look {
            Look::StartText => pos == 0,
            Look::EndText => pos == hay.len(),
            Look::StartLine => pos == 0 || hay[pos - 1] == b'\n',
            Look::EndLine => pos == hay.len() || hay[pos] == b'\n',
            Look::WordUnicode => self.word_before(hay, pos) != self.word_after(hay, pos),
            Look::WordUnicodeNegate => {
                self.word_before(hay, pos) == self.word_after(hay, pos)
            }
            Look::WordAscii => {
                self.word_byte_before(hay, pos) != self.word_byte_after(hay, pos)
            }
            Look::WordAsciiNegate => {
                self.word_byte_before(hay, pos) == self.word_byte_after(hay, pos)
            }
            Look::WordStartUnicode => {
                !self.word_before(hay, pos) && self.word_after(hay, pos)
            }
            Look::WordEndUnicode => self.word_before(hay, pos) && !self.word_after(hay, pos),
            Look::WordStartHalfUnicode => !self.word_before(hay, pos),
            Look::WordEndHalfUnicode => !self.word_after(hay, pos),
            Look::WordStartAscii => {
                !self.word_byte_before(hay, pos) && self.word_byte_after(hay, pos)
            }
            Look::WordEndAscii => {
                self.word_byte_before(hay, pos) && !self.word_byte_after(hay, pos)
            }
            Look::WordStartHalfAscii => !self.word_byte_before(hay, pos),
            Look::WordEndHalfAscii => !self.word_byte_after(hay, pos),
        }
    }

    fn word_before(&self, hay: &[u8], pos: usize) -> bool {
        match decode_utf8_back(hay, pos) {
            Some((c, _)) => self.word.is_word_char(c),
            None => false,
        }
    }

    fn word_after(&self, hay: &[u8], pos: usize) -> bool {
        match decode_utf8(hay, pos) {
            Some((c, _)) => self.word.is_word_char(c),
            None => false,
        }
    }

    fn word_byte_before(&self, hay: &[u8], pos: usize) -> bool {
        pos > 0 && self.word.is_word_byte(hay[pos - 1])
    }

    fn word_byte_after(&self, hay: &[u8], pos: usize) -> bool {
        pos < hay.len() && self.word.is_word_byte(hay[pos])
    }
}

fn set_allows_eof(_set: &[bool; 256]) -> bool {
