//! A small regular expression engine that mirrors the syntax and match
//! semantics of the Rust `regex` crate closely enough to be a drop-in
//! replacement for this tool.

mod error;
mod exec;
mod hir;
mod parser;
mod program;
mod unicode;

pub use error::Error;
pub use parser::Flags;

use exec::Matcher;
use program::Program;

pub struct Regex {
    program: Program,
    capture_names: Vec<Option<String>>,
}

/// One match, with the spans of every capture group.
pub struct Captures {
    slots: Vec<Option<usize>>,
}

impl Captures {
    pub fn get(&self, group: usize) -> Option<(usize, usize)> {
        let s = self.slots.get(2 * group).copied().flatten()?;
        let e = self.slots.get(2 * group + 1).copied().flatten()?;
        Some((s, e))
    }
}

impl Regex {
    pub fn new(pattern: &str, flags: Flags) -> Result<Regex, Error> {
        let parsed = parser::Parser::new(pattern, flags).parse()?;
        let groups = parsed.capture_names.len() - 1;
        let program = program::compile(&parsed.hir, groups)?;
        Ok(Regex {
            program,
            capture_names: parsed.capture_names,
        })
    }

    pub fn group_index(&self, name: &str) -> Option<usize> {
        self.capture_names
            .iter()
            .position(|n| n.as_deref() == Some(name))
    }

    pub fn group_count(&self) -> usize {
        self.capture_names.len() - 1
    }

    /// Iterates over non-overlapping matches, following the same rule as the
    /// reference engine for empty matches: an empty match that lands exactly
    /// where the previous match ended is discarded.
    pub fn for_each_match<F>(&self, hay: &[u8], limit: usize, mut f: F)
    where
        F: FnMut(&Captures),
    {
        let mut matcher = Matcher::new(&self.program);
        let mut caps = Captures {
            slots: vec![None; self.program.slots],
        };
        let mut at = 0usize;
        let mut last_end: Option<usize> = None;
        let mut count = 0usize;
        while at <= hay.len() {
            let Some((start, end)) = matcher.find_at(hay, at, &mut caps.slots) else {
                break;
            };
            if start == end && Some(end) == last_end {
                at = end + 1;
                continue;
            }
            f(&caps);
            count += 1;
            if limit != 0 && count >= limit {
                break;
            }
            last_end = Some(end);
            at = if start == end { end + 1 } else { end };
        }
    }
}

