            | Inst::Mark { next, .. }
            | Inst::Progress { next, .. } => self.is_anchored(*next, seen),
            Inst::Split { a, b } => self.is_anchored(*a, seen) && self.is_anchored(*b, seen),
            Inst::Bytes { bytes, next } if bytes.is_empty() => self.is_anchored(*next, seen),
            _ => false,
        }
    }
}

