pub fn find_at(
    &mut self,
    hay: &[u8],
    at: usize,
    slots: &mut [Option<usize>],
) -> Option<(usize, usize)> {
    let mut start = at;
    loop {
        if start > hay.len() {
            return None;
        }
        if let Some(set) = &self.program.first_bytes {
