//! Turns the REPLACE_WITH argument into a template and applies it to matches.

use std::fmt;

use crate::rx::{Captures, Regex};

/// One piece of a replacement template.
enum Chunk {
    Literal(Vec<u8>),
    /// A capture group referenced by number.
    Index(usize),
    /// A capture group referenced by name.
    Name(String),
}

pub struct Template {
    chunks: Vec<Chunk>,
}

/// A `$1abc`-style reference, where the digits and the trailing name characters
/// run together and could mean either group 1 followed by text or a group
/// literally named `1abc`.
pub struct AmbiguousCapture {
    replacement: String,
    /// Character offset of the name (just past the `$`).
    offset: usize,
    digits: String,
    rest: String,
}

impl fmt::Display for AmbiguousCapture {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(
            f,
            "The numbered capture group `${}` in the replacement text is ambiguous.",
            self.digits
        )?;
        writeln!(
            f,
            "hint: Use curly braces to disambiguate it `${{{}}}{}`.",
            self.digits, self.rest
        )?;
        writeln!(f, "{}", self.replacement)?;
        let width = self.digits.chars().count() + self.rest.chars().count();
        write!(
            f,
            "{}{}",
            " ".repeat(self.offset),
            "^".repeat(width)
        )
    }
}

impl Template {
    /// A template that emits `text` verbatim, used by `--fixed-strings`.
    pub fn literal(text: &str) -> Template {
        Template {
            chunks: vec![Chunk::Literal(text.as_bytes().to_vec())],
        }
    }

    /// Parses `$1`, `${name}` and `$$` references out of `text`.
    pub fn parse(text: &str) -> Result<Template, AmbiguousCapture> {
        let bytes = text.as_bytes();
        let mut chunks: Vec<Chunk> = Vec::new();
        let mut literal: Vec<u8> = Vec::new();
        let mut i = 0usize;
        while i < bytes.len() {
            if bytes[i] != b'$' {
                literal.push(bytes[i]);
                i += 1;
                continue;
            }
            if bytes.get(i + 1) == Some(&b'$') {
                literal.push(b'$');
                i += 2;
                continue;
            }
            match parse_reference(bytes, i) {
                None => {
                    literal.push(b'$');
                    i += 1;
                }
                Some(reference) => {
                    if let Some(rest) = reference.ambiguous_suffix() {
                        let digits: String = reference
                            .name
                            .chars()
                            .take(reference.name.chars().count() - rest.chars().count())
                            .collect();
                        return Err(AmbiguousCapture {
                            replacement: text.to_string(),
                            offset: text[..i + 1].chars().count(),
                            digits,
                            rest: rest.to_string(),
                        });
                    }
                    if !literal.is_empty() {
                        chunks.push(Chunk::Literal(std::mem::take(&mut literal)));
                    }
                    chunks.push(match reference.name.parse::<usize>() {
                        Ok(index) => Chunk::Index(index),
                        Err(_) => Chunk::Name(reference.name.to_string()),
                    });
                    i = reference.end;
                }
            }
        }
        if !literal.is_empty() {
            chunks.push(Chunk::Literal(literal));
        }
        Ok(Template { chunks })
    }

    /// Appends this template, with `caps` substituted, to `out`.
    pub fn expand(&self, hay: &[u8], caps: &Captures, regex: &Regex, out: &mut Vec<u8>) {
        for chunk in &self.chunks {
            match chunk {
                Chunk::Literal(bytes) => out.extend_from_slice(bytes),
                Chunk::Index(index) => {
                    if let Some((s, e)) = caps.get(*index) {
                        out.extend_from_slice(&hay[s..e]);
                    }
                }
                Chunk::Name(name) => {
                    if let Some(index) = regex.group_index(name) {
                        if let Some((s, e)) = caps.get(index) {
                            out.extend_from_slice(&hay[s..e]);
                        }
                    }
                }
            }
        }
    }
}

struct Reference<'a> {
    name: &'a str,
    /// Byte offset just past the reference.
    end: usize,
    braced: bool,
}

impl<'a> Reference<'a> {
    /// For `$12ab`, returns `Some("ab")`: a numbered group whose digits are
    /// followed by more name characters, which reads ambiguously.
    fn ambiguous_suffix(&self) -> Option<&'a str> {
        if self.braced {
            return None;
        }
        let digits = self
            .name
            .find(|c: char| !c.is_ascii_digit())
            .unwrap_or(self.name.len());
        if digits == 0 || digits == self.name.len() {
            return None;
        }
        Some(&self.name[digits..])
    }
}

/// Parses the reference beginning at the `$` in `bytes[at]`.
fn parse_reference(bytes: &[u8], at: usize) -> Option<Reference<'_>> {
    let mut i = at + 1;
    if bytes.get(i) == Some(&b'{') {
        i += 1;
        let start = i;
        while i < bytes.len() && bytes[i] != b'}' {
            i += 1;
        }
        if bytes.get(i) != Some(&b'}') {
            return None;
        }
        let name = std::str::from_utf8(&bytes[start..i]).ok()?;
        return Some(Reference {
            name,
            end: i + 1,
            braced: true,
        });
    }
    let start = i;
    while i < bytes.len() && is_name_byte(bytes[i]) {
        i += 1;
    }
    if i == start {
        return None;
    }
    let name = std::str::from_utf8(&bytes[start..i]).ok()?;
    Some(Reference {
        name,
        end: i,
        braced: false,
    })
}

fn is_name_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

