//! Command line parsing, plus the help and diagnostic text that goes with it.

use std::ffi::{OsStr, OsString};
use std::path::PathBuf;

pub struct Options {
    pub preview: bool,
    pub fixed_strings: bool,
    pub max_replacements: usize,
    pub flags: Option<String>,
    pub find: String,
    pub replace_with: String,
    pub files: Vec<PathBuf>,
}

const NAME: &str = "sd";
const VERSION: &str = "1.0.0";
const ABOUT: &str = "sd v1.0.0\nAn intuitive find & replace CLI";
const MAX_WIDTH: usize = 100;
const NEXT_LINE_INDENT: usize = 10;

/// Description of one command line option, used for both parsing and help.
struct OptSpec {
    short: char,
    long: &'static str,
    value: Option<&'static str>,
    help: &'static str,
    long_help: &'static str,
    /// Extra text clap appends, such as the default value.
    spec_vals: Option<&'static str>,
}

const OPTS: &[OptSpec] = &[
    OptSpec {
        short: 'p',
        long: "preview",
        value: None,
        help: "Display changes in a human reviewable format (the specifics of the format are \
               likely to change in the future)",
        long_help: "Display changes in a human reviewable format (the specifics of the format \
                    are likely to change in the future)",
        spec_vals: None,
    },
    OptSpec {
        short: 'F',
        long: "fixed-strings",
        value: None,
        help: "Treat FIND and REPLACE_WITH args as literal strings",
        long_help: "Treat FIND and REPLACE_WITH args as literal strings",
        spec_vals: None,
    },
    OptSpec {
        short: 'n',
        long: "max-replacements",
        value: Some("LIMIT"),
        help: "Limit the number of replacements that can occur per file. 0 indicates unlimited \
               replacements",
        long_help: "Limit the number of replacements that can occur per file. 0 indicates \
                    unlimited replacements",
        spec_vals: Some("[default: 0]"),
    },
    OptSpec {
        short: 'f',
        long: "flags",
        value: Some("FLAGS"),
        help: "Regex flags. May be combined (like `-f mc`).",
        long_help: "Regex flags. May be combined (like `-f mc`).\n\nc - case-sensitive\n\ne - \
                    disable multi-line matching\n\ni - case-insensitive\n\nm - multi-line \
                    matching\n\ns - make `.` match newlines\n\nw - match full words only",
        spec_vals: None,
    },
    OptSpec {
        short: 'h',
        long: "help",
        value: None,
        help: "Print help (see more with '--help')",
        long_help: "Print help (see a summary with '-h')",
        spec_vals: None,
    },
    OptSpec {
        short: 'V',
        long: "version",
        value: None,
        help: "Print version",
        long_help: "Print version",
        spec_vals: None,
    },
];

const ARGS: &[(&str, &str, &str)] = &[
    (
        "<FIND>",
        "The regexp or string (if using `-F`) to search for",
        "The regexp or string (if using `-F`) to search for",
    ),
    (
        "<REPLACE_WITH>",
        "What to replace each match with. Unless in string mode, you may use captured values \
         like $1, $2, etc",
        "What to replace each match with. Unless in string mode, you may use captured values \
         like $1, $2, etc",
    ),
    (
        "[FILES]...",
        "The path to file(s). This is optional - sd can also read from STDIN",
        "The path to file(s). This is optional - sd can also read from STDIN.\n\nNote: sd \
         modifies files in-place by default. See documentation for examples.",
    ),
];

/// Parses the command line, printing help/version or an error and exiting when
/// appropriate.
pub fn parse() -> Options {
    let mut argv = std::env::args_os();
    let program = argv.next().unwrap_or_else(|| OsString::from(NAME));
    let bin = binary_name(&program);
    let args: Vec<OsString> = argv.collect();
    match Parser::new(&bin).run(args) {
        Ok(Outcome::Options(options)) => options,
        Ok(Outcome::Help { long }) => {
            print!("{}", render_help(&bin, long, term_width()));
            std::process::exit(0);
        }
        Ok(Outcome::Version) => {
            println!("{NAME} {VERSION}");
            std::process::exit(0);
        }
        Err(err) => {
            eprint!("{err}");
            std::process::exit(2);
        }
    }
}

fn binary_name(program: &OsStr) -> String {
    PathBuf::from(program)
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| NAME.to_string())
}

enum Outcome {
    Options(Options),
    Help { long: bool },
    Version,
}

struct Parser<'a> {
    bin: &'a str,
    /// Long names of the options seen so far, in command line order; used to
    /// build the usage line shown with errors.
    used: Vec<String>,
    preview: bool,
    fixed_strings: bool,
    max_replacements: Option<usize>,
    flags: Option<String>,
    positionals: Vec<OsString>,
}

impl<'a> Parser<'a> {
    fn new(bin: &'a str) -> Parser<'a> {
        Parser {
            bin,
            used: Vec::new(),
            preview: false,
            fixed_strings: false,
            max_replacements: None,
            flags: None,
            positionals: Vec::new(),
        }
    }

    fn run(mut self, args: Vec<OsString>) -> Result<Outcome, String> {
        let mut iter = args.into_iter().peekable();
        let mut only_positional = false;
        while let Some(arg) = iter.next() {
            if only_positional {
                self.positionals.push(arg);
                continue;
            }
            let text = arg.to_string_lossy().into_owned();
            if text == "--" {
                only_positional = true;
                continue;
            }
            if let Some(long) = text.strip_prefix("--") {
                let (name, inline) = match long.split_once('=') {
                    Some((name, value)) => (name, Some(value.to_string())),
                    None => (long, None),
                };
                let Some(spec) = OPTS.iter().find(|o| o.long == name) else {
                    return Err(self.unexpected_argument(&format!("--{name}")));
                };
                if let Some(outcome) = self.apply(spec, inline, &mut iter)? {
                    return Ok(outcome);
                }
                continue;
            }
            if text.len() > 1 && text.starts_with('-') {
                let cluster: Vec<char> = text.chars().skip(1).collect();
                let mut index = 0;
                while index < cluster.len() {
                    let c = cluster[index];
                    let Some(spec) = OPTS.iter().find(|o| o.short == c) else {
                        return Err(self.unexpected_argument(&format!("-{c}")));
                    };
                    index += 1;
                    let inline = if spec.value.is_some() && index < cluster.len() {
                        let rest: String = cluster[index..].iter().collect();
                        index = cluster.len();
                        Some(rest)
                    } else {
                        None
                    };
                    if let Some(outcome) = self.apply(spec, inline, &mut iter)? {
                        return Ok(outcome);
                    }
                }
                continue;
            }
            self.positionals.push(arg);
        }
        self.finish()
    }

    /// Records one occurrence of `spec`, consuming its value if it takes one.
    fn apply(
        &mut self,
        spec: &OptSpec,
        inline: Option<String>,
        iter: &mut std::iter::Peekable<std::vec::IntoIter<OsString>>,
    ) -> Result<Option<Outcome>, String> {
        if spec.value.is_none() {
            if let Some(value) = inline {
                return Err(self.unexpected_value(spec, &value));
            }
        }
        match spec.long {
            "help" => return Ok(Some(Outcome::Help { long: true })),
            "version" => return Ok(Some(Outcome::Version)),
            _ => {}
        }
        let already = match spec.long {
            "preview" => self.preview,
            "fixed-strings" => self.fixed_strings,
            "max-replacements" => self.max_replacements.is_some(),
            _ => self.flags.is_some(),
        };
        if already {
            return Err(self.duplicate(spec));
        }
        self.used.push(usage_fragment(spec));
        match spec.value {
            None => {
                match spec.long {
                    "preview" => self.preview = true,
                    _ => self.fixed_strings = true,
                }
                Ok(None)
            }
            Some(_) => {
                let value = match inline {
                    Some(value) => value,
                    None => match iter.peek() {
                        Some(next) if !looks_like_flag(next) => {
                            iter.next().unwrap().to_string_lossy().into_owned()
                        }
                        _ => return Err(self.missing_value(spec)),
                    },
                };
                if spec.long == "max-replacements" {
                    match value.parse::<usize>() {
                        Ok(n) => self.max_replacements = Some(n),
                        Err(err) => {
                            return Err(self.invalid_value(spec, &value, &int_error(&err, &value)))
                        }
                    }
                } else {
                    self.flags = Some(value);
                }
                Ok(None)
            }
        }
    }

    fn finish(mut self) -> Result<Outcome, String> {
        let mut missing: Vec<&str> = Vec::new();
        if self.positionals.is_empty() {
            missing.push("<FIND>");
        }
        if self.positionals.len() < 2 {
            missing.push("<REPLACE_WITH>");
        }
        if !missing.is_empty() {
            let list: String = missing
                .iter()
                .map(|m| format!("  {m}\n"))
                .collect::<Vec<_>>()
                .join("");
            return Err(format!(
                "error: the following required arguments were not provided:\n{list}\n\
                 Usage: {}\n\nFor more information, try '--help'.\n",
                self.usage_bare()
            ));
        }
        let mut rest = self.positionals.drain(..);
        let find = rest.next().unwrap();
        let replace_with = rest.next().unwrap();
        let (Some(find), Some(replace_with)) = (find.to_str(), replace_with.to_str()) else {
            return Err(format!(
                "error: invalid UTF-8 was detected in one or more arguments\n\n\
                 Usage: {} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n\
                 For more information, try '--help'.\n",
                self.bin
            ));
        };
        Ok(Outcome::Options(Options {
            preview: self.preview,
            fixed_strings: self.fixed_strings,
            max_replacements: self.max_replacements.unwrap_or(0),
            flags: self.flags,
            find: find.to_string(),
            replace_with: replace_with.to_string(),
            files: rest.map(PathBuf::from).collect(),
        }))
    }

    // -- error rendering ---------------------------------------------------

    /// `[OPTIONS]` or the options actually used, followed by the positionals.
    fn usage_bare(&self) -> String {
        if self.used.is_empty() {
            format!("{} <FIND> <REPLACE_WITH> [FILES]...", self.bin)
        } else {
            format!(
                "{} {} <FIND> <REPLACE_WITH> [FILES]...",
                self.bin,
                self.used.join(" ")
            )
        }
    }

    fn usage_options(&self) -> String {
        if self.used.is_empty() {
            format!("{} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...", self.bin)
        } else {
            self.usage_bare()
        }
    }

    fn unexpected_argument(&self, arg: &str) -> String {
        let tip = match closest_long(arg) {
            Some(similar) => format!("  tip: a similar argument exists: '--{similar}'\n"),
            None => format!("  tip: to pass '{arg}' as a value, use '-- {arg}'\n"),
        };
        let usage = if closest_long(arg).is_some() {
            format!(
                "{} <--preview|--fixed-strings|--max-replacements <LIMIT>|--flags <FLAGS>|\
                 FIND|REPLACE_WITH|FILES>",
                self.bin
            )
        } else {
            self.usage_options()
        };
        format!(
            "error: unexpected argument '{arg}' found\n\n{tip}\nUsage: {usage}\n\n\
             For more information, try '--help'.\n"
        )
    }

    fn unexpected_value(&self, spec: &OptSpec, value: &str) -> String {
        format!(
            "error: unexpected value '{value}' for '--{}' found; no more were expected\n\n\
             Usage: {} --{} <FIND> <REPLACE_WITH> [FILES]...\n\n\
             For more information, try '--help'.\n",
            spec.long, self.bin, spec.long
        )
    }

    fn duplicate(&self, spec: &OptSpec) -> String {
        format!(
            "error: the argument '{}' cannot be used multiple times\n\nUsage: {}\n\n\
             For more information, try '--help'.\n",
            usage_fragment(spec),
            self.usage_options()
        )
    }

    fn missing_value(&self, spec: &OptSpec) -> String {
        format!(
            "error: a value is required for '{}' but none was supplied\n\n\
             For more information, try '--help'.\n",
            usage_fragment(spec)
        )
    }

    fn invalid_value(&self, spec: &OptSpec, value: &str, reason: &str) -> String {
        format!(
            "error: invalid value '{value}' for '{}': {reason}\n\n\
             For more information, try '--help'.\n",
            usage_fragment(spec)
        )
    }
}

fn usage_fragment(spec: &OptSpec) -> String {
    match spec.value {
        Some(value) => format!("--{} <{value}>", spec.long),
        None => format!("--{}", spec.long),
    }
}

fn looks_like_flag(arg: &OsStr) -> bool {
    let text = arg.to_string_lossy();
    text.len() > 1 && text.starts_with('-')
}

fn int_error(err: &std::num::ParseIntError, value: &str) -> String {
    // Mirrors the standard library's messages, which clap passes through.
    let _ = err;
    if value.is_empty() {
        "cannot parse integer from empty string".to_string()
    } else if value.chars().all(|c| c.is_ascii_digit()) {
        "number too large to fit in target type".to_string()
    } else {
        "invalid digit found in string".to_string()
    }
}

/// Finds a long option name similar to `arg`, the way clap suggests fixes.
fn closest_long(arg: &str) -> Option<&'static str> {
    let candidate = arg.trim_start_matches('-');
    if candidate.is_empty() {
        return None;
    }
    let mut best: Option<(f64, &'static str)> = None;
    for opt in OPTS {
        let score = jaro_winkler(candidate, opt.long);
        if score > 0.7 && best.map_or(true, |(b, _)| score > b) {
            best = Some((score, opt.long));
        }
    }
    best.map(|(_, name)| name)
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro = jaro(a, b);
    if jaro <= 0.7 {
        return jaro;
    }
    let prefix = a
        .chars()
        .zip(b.chars())
        .take(4)
        .take_while(|(x, y)| x == y)
        .count() as f64;
    jaro + 0.1 * prefix * (1.0 - jaro)
}

fn jaro(a: &str, b: &str) -> f64 {
    let x: Vec<char> = a.chars().collect();
    let y: Vec<char> = b.chars().collect();
    if x.is_empty() || y.is_empty() {
        return 0.0;
    }
    let window = (x.len().max(y.len()) / 2).saturating_sub(1);
    let mut x_used = vec![false; x.len()];
    let mut y_used = vec![false; y.len()];
    let mut matches = 0usize;
    for (i, xc) in x.iter().enumerate() {
        let lo = i.saturating_sub(window);
        let hi = (i + window + 1).min(y.len());
        for j in lo..hi {
            if !y_used[j] && *xc == y[j] {
                x_used[i] = true;
                y_used[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for (i, used) in x_used.iter().enumerate() {
        if !*used {
            continue;
        }
        while !y_used[k] {
            k += 1;
        }
        if x[i] != y[k] {
            transpositions += 1;
        }
        k += 1;
    }
    let m = matches as f64;
    (m / x.len() as f64 + m / y.len() as f64 + (m - transpositions as f64 / 2.0) / m) / 3.0
}

// ---------------------------------------------------------------------------
// Help rendering
// ---------------------------------------------------------------------------

/// The width help text is laid out for: the terminal if there is one, else
/// `COLUMNS`, else 100 — never more than 100.
fn term_width() -> usize {
    if let Some(width) = tty_width() {
        return width.min(MAX_WIDTH);
    }
    if let Ok(columns) = std::env::var("COLUMNS") {
        if let Ok(width) = columns.parse::<usize>() {
            return width.min(MAX_WIDTH);
        }
    }
    MAX_WIDTH
}

fn tty_width() -> Option<usize> {
    #[repr(C)]
    struct WinSize {
        rows: u16,
        cols: u16,
        xpixel: u16,
        ypixel: u16,
    }
    extern "C" {
        fn ioctl(fd: i32, request: libc_request, ...) -> i32;
    }
    #[allow(non_camel_case_types)]
    type libc_request = u64;
    const TIOCGWINSZ: libc_request = 0x5413;
    for fd in [1, 2, 0] {
        let mut size = WinSize {
            rows: 0,
            cols: 0,
            xpixel: 0,
            ypixel: 0,
        };
        let ok = unsafe { ioctl(fd, TIOCGWINSZ, &mut size as *mut WinSize) };
        if ok == 0 && size.cols > 0 {
            return Some(size.cols as usize);
        }
    }
    None
}

pub fn render_help(bin: &str, long: bool, width: usize) -> String {
    let mut out = String::new();
    for line in wrap(ABOUT, width) {
        out.push_str(&line);
        out.push('\n');
    }
    out.push('\n');
    out.push_str(&format!(
        "Usage: {bin} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n"
    ));

    let arg_entries: Vec<Entry> = ARGS
        .iter()
        .map(|(name, help, long_help)| Entry {
            name: (*name).to_string(),
            help: if long { long_help } else { help },
            spec_vals: None,
        })
        .collect();
    let opt_entries: Vec<Entry> = OPTS
        .iter()
        .map(|o| Entry {
            name: match o.value {
                Some(value) => format!("-{}, --{} <{value}>", o.short, o.long),
                None => format!("-{}, --{}", o.short, o.long),
            },
            help: if long { o.long_help } else { o.help },
            spec_vals: o.spec_vals,
        })
        .collect();

    out.push_str("Arguments:\n");
    out.push_str(&render_section(&arg_entries, long, width));
    out.push('\n');
    out.push_str("Options:\n");
    out.push_str(&render_section(&opt_entries, long, width));
    out
}

struct Entry {
    name: String,
    help: &'static str,
    spec_vals: Option<&'static str>,
}

fn render_section(entries: &[Entry], long: bool, width: usize) -> String {
    let longest = entries
        .iter()
        .map(|e| e.name.chars().count())
        .max()
        .unwrap_or(2);
    let help_col = longest + 4;
    // Same-line help is used when the terminal is wide enough to be worth it;
    // long help always puts the description on its own line.
    let next_line = long || (width >= help_col && width * 2 < help_col * 5);
    let mut out = String::new();
    for (i, entry) in entries.iter().enumerate() {
        let text = match entry.spec_vals {
            Some(vals) if long => format!("{}\n\n{vals}", entry.help),
            Some(vals) => format!("{} {vals}", entry.help),
            None => entry.help.to_string(),
        };
        if next_line {
            if long && i > 0 {
                out.push('\n');
            }
            out.push_str(&format!("  {}\n", entry.name));
            let avail = width.saturating_sub(NEXT_LINE_INDENT);
            for line in wrap(&text, avail) {
                out.push_str(&" ".repeat(NEXT_LINE_INDENT));
                out.push_str(&line);
                out.push('\n');
            }
        } else {
            let avail = width.saturating_sub(help_col);
            let lines = wrap(&text, avail);
            let pad = longest - entry.name.chars().count();
            out.push_str(&format!(
                "  {}{}  {}\n",
                entry.name,
                " ".repeat(pad),
                lines.first().map(String::as_str).unwrap_or("")
            ));
            for line in lines.iter().skip(1) {
                out.push_str(&" ".repeat(help_col));
                out.push_str(line);
                out.push('\n');
            }
        }
    }
    out
}

/// Greedy word wrapping.  Existing newlines are kept, and a word longer than
/// the available width is left on a line of its own rather than split.
fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut out = Vec::new();
    for paragraph in text.split('\n') {
        let mut line = String::new();
        for word in paragraph.split_whitespace() {
            if line.is_empty() {
                line.push_str(word);
            } else if line.chars().count() + 1 + word.chars().count() <= width {
                line.push(' ');
                line.push_str(word);
            } else {
                out.push(std::mem::take(&mut line));
                line.push_str(word);
            }
        }
        out.push(line);
    }
    out
}

